let activeCraftingTabKey = null;
/** recipeId -> batch quantity (1–999) in crafting panel */
const craftBatchQtyByRecipe = new Map();
/** @type {null | object} */
let pendingCraftInvitePayload = null;
let clientMaterialDifficultyIndex = null;
let atlasSearchQuery = "";
let atlasSelectedRegionName = null;
let atlasSelectedMonsterName = null;
const atlasExpandedRegions = new Set();
let activeMenuPanel = null;
let dragPayload = null;
/** Respawn label updates on adventure (no full re-render — avoids image flash) */
let adventureRespawnTick = null;
/** +HP per second while fight overlay is closed and {@link combatState} is null. */
let outOfCombatHpRegenTick = null;
/** Companion slot waiting for its one-time character creation before first enable. */
let pendingCompanionEnableSlot = null;
/** Hero roster slot index waiting for character creation (`0`–`4`). */
