let characterPanelRosterTab = "hero";
/** Set while the characteristic-point spend modal is open ({@link openCharPointSpendModal}). Cleared in {@link closeModal}. */
let pendingCharSpend = null;

const COMPANION_SLOT_COUNT = 3;
const CHARACTER_SLOT_COUNT = 5;
const COMPANION_LOOT_CHANCE_MULT = 0.75;
/** Per-tile panel positions until wander bucket changes — avoids re-rolling on every render (no micro-jump on map open). */
const campPanelLayoutCache = new Map();
/** Sampled average RGB from each tile's adventure background image (world map + minimap). */
const mapCellArtColorByTileKey = new Map();
const mapCellArtColorByUrl = new Map();
const mapCellArtProbePending = new Set();
const mapCellArtProbeFailed = new Set();
let mapArtNotifyRaf = null;
/** Cells visible in each direction from player when opening world map modal (20 → 41×41 tiles) */
const WORLD_MAP_MODAL_NEIGHBOR_RADIUS = 20;
/** Landscape tiles: width = height × this ratio (length = 2× width in the sense of horizontal span). */
const WORLD_MAP_CELL_WIDTH_PER_HEIGHT = 2;
/** Most zoomed-out tile size (cell height in px; width = height × {@link WORLD_MAP_CELL_WIDTH_PER_HEIGHT}). */
const WORLD_MAP_MODAL_MIN_CELL_HEIGHT_PX = 10;
/** Pixel height of each map cell in the world map modal (zoom); width = height × {@link WORLD_MAP_CELL_WIDTH_PER_HEIGHT}. Persists for the session. */
let worldMapModalCellPx = 8;

function worldMapModalCellDims() {
  const cellH = worldMapModalCellPx;
  return { cellW: cellH * WORLD_MAP_CELL_WIDTH_PER_HEIGHT, cellH };
}
/** First time the world map modal opens this session, apply a stronger default zoom; after that, reuse {@link worldMapModalCellPx}. */
let worldMapModalZoomInitialized = false;
const WORLD_MAP_MODAL_FIRST_OPEN_ZOOM_MULT = 10;
const WORLD_MAP_MODAL_ZOOM_STEP = 1.08;

function ensurePlayerPetState(p) {
  if (typeof PET_SYSTEM !== "undefined" && PET_SYSTEM && typeof PET_SYSTEM.ensurePlayerPetState === "function") {
    PET_SYSTEM.ensurePlayerPetState(p);
  }
}

function isPetItemDef(def) {
  return !!(def && def.type === "pet");
}

function isPetInstanceItemName(itemName) {
  return typeof PET_SYSTEM !== "undefined" && PET_SYSTEM && PET_SYSTEM.isPetInstanceName(itemName);
}

function getPetProgressOwner(actor) {
  if (actor && typeof actor === "object") {
    if (
      inGameSession &&
      player &&
      actor !== player &&
      Array.isArray(player.companions) &&
      player.companions.includes(actor)
    ) {
      return player;
    }
    return actor;
  }
  return player;
}

function getPetDisplayImage(itemName, progressOwner) {
  if (!isPetInstanceItemName(itemName)) return getItemImage(itemName);
  if (typeof PET_SYSTEM === "undefined" || !PET_SYSTEM) return getItemImage(itemName);
  const base = getItemBaseName(itemName);
  const progOwner = getPetProgressOwner(progressOwner);
  const prog =
    progOwner && typeof PET_SYSTEM.getPetProgress === "function"
      ? PET_SYSTEM.getPetProgress(progOwner, itemName)
      : { level: 1 };
  return PET_SYSTEM.getPetImage(base, prog.level);
}

function getPetPortraitLayoutCategory(baseName) {
  if (typeof PETS_CATALOG !== "undefined" && PETS_CATALOG && typeof PETS_CATALOG.getPetPortraitLayoutCategory === "function") {
    return PETS_CATALOG.getPetPortraitLayoutCategory(baseName);
  }
  return "ground";
}

function getPortraitPetVisualStage(petInstance, progressOwner) {
  if (!petInstance || typeof PET_PROGRESSION === "undefined" || !PET_PROGRESSION || typeof PET_SYSTEM === "undefined" || !PET_SYSTEM) {
    return "young";
  }
  const progOwner = getPetProgressOwner(progressOwner);
  if (!progOwner) return "young";
  const { level } = PET_SYSTEM.getPetProgress(progOwner, petInstance);
  return PET_PROGRESSION.getVisualStage(level);
}

function getPortraitPetStageLayoutKey(petInstance, progressOwner) {
  const stage = getPortraitPetVisualStage(petInstance, progressOwner);
  const base = petInstance ? getItemBaseName(petInstance) : "";
  const category = getPetPortraitLayoutCategory(base);
  return `pet_${stage}_${category}`;
}

function getEquippedPetBonusStats(equipment, progressOwner) {
  if (!equipment || typeof equipment !== "object" || !equipment.pet) return {};
  if (typeof PET_SYSTEM === "undefined" || !PET_SYSTEM) return {};
  const progOwner = getPetProgressOwner(progressOwner);
  if (!progOwner) return {};
  const base = getItemBaseName(equipment.pet);
  const { level } = PET_SYSTEM.getPetProgress(progOwner, equipment.pet);
  return PET_SYSTEM.getPetBonusStats(base, level);
}

function equipmentSlotsForActor(actor, rosterTab) {
  return EQUIP_SLOTS;
}

function normalizePetInventoryEntry(p, itemName) {
  if (typeof PET_SYSTEM === "undefined" || !PET_SYSTEM) return itemName;
  const def = getItemDef(itemName);
  if (!isPetItemDef(def)) return itemName;
  if (PET_SYSTEM.isPetInstanceName(itemName)) {
    ensurePlayerPetState(p);
    const { instanceId } = PET_SYSTEM.splitInstance(itemName);
    if (instanceId && !p.petProgress[instanceId]) p.petProgress[instanceId] = { level: 1, xp: 0 };
    return itemName;
  }
  ensurePlayerPetState(p);
  const base = getItemBaseName(itemName);
  const id = PET_SYSTEM.newInstanceId();
  const inst = PET_SYSTEM.makePetInstanceName(base, id);
  p.petProgress[id] = { level: 1, xp: 0 };
  return inst;
}

function reconcilePetInventoryInstances(p) {
  if (!p || !Array.isArray(p.inventory)) return;
  p.inventory = p.inventory.map((entry) => (typeof entry === "string" ? normalizePetInventoryEntry(p, entry) : entry));
  const eq = p.equipment && typeof p.equipment === "object" ? p.equipment : null;
  if (eq && typeof eq.pet === "string" && eq.pet) eq.pet = normalizePetInventoryEntry(p, eq.pet);
  if (Array.isArray(p.companions)) {
    p.companions.forEach((c) => {
      if (c && c.equipment && typeof c.equipment.pet === "string" && c.equipment.pet) {
        c.equipment.pet = normalizePetInventoryEntry(p, c.equipment.pet);
      }
    });
  }
}

function emptyEquipment() {
  return {
    head: null,
    amulet: null,
    chest: null,
    weapon: null,
    offhand: null,
    bracelet: null,
    legs: null,
    feet: null,
    ring1: null,
    ring2: null,
    pet: null
  };
}

function getStarterEquipment() {
  return {
    ...emptyEquipment(),
    chest: "Raggs Shirt",
    weapon: "Rusty Sword",
    legs: "Raggs Pants"
  };
}

function equipStarterGearIfEmpty(actor) {
  if (!actor || typeof actor !== "object") return;
  const starter = getStarterEquipment();
  const eq = actor.equipment && typeof actor.equipment === "object" ? actor.equipment : emptyEquipment();
  if (!eq.weapon) eq.weapon = starter.weapon;
  if (!eq.chest) eq.chest = starter.chest;
  if (!eq.legs) eq.legs = starter.legs;
  actor.equipment = { ...emptyEquipment(), ...eq };
}

function createDefaultCompanionSlot(label) {
  const classSkillLevels = {};
  const companion = {
    enabled: false,
    hasBeenEnabled: false,
    name: label,
    level: 1,
    xp: 0,
    hp: 100,
    maxHp: 100,
    str: 5,
    dex: 5,
    vit: 5,
    int: 5,
    baseAttack: 10,
    charPoints: 0,
    skillPoints: 1,
    allocPoolsBindToLevelV2: true,
    allocPoolsCharV2: true,
    classId: DEFAULT_CLASS_ID,
    classSkillLevels,
    skills: [],
    professions: [],
    equipment: getStarterEquipment(),
    portraitGender: "male",
    portraitLayouts: {}
  };
  companion.maxHp = computeMaxHp(companion);
  companion.hp = companion.maxHp;
  syncPlayerClassSkillList(companion);
  ensureActorSkillBar(companion);
  recomputeAllocPoolsFromLevel(companion);
  return companion;
}

/** Keep companion progression data separate from the hero (guards bad saves / mistaken references). */
function isolateCompanionProgressFromHero(p, c, slotIndex) {
  if (!p || !c || c !== p) return c;
  const replacement = createDefaultCompanionSlot(`Companion ${slotIndex + 1}`);
  p.companions[slotIndex] = replacement;
  return replacement;
}

function ensurePlayerCompanions(p) {
  if (!p || typeof p !== "object") return;
  if (!Array.isArray(p.companions) || p.companions.length !== COMPANION_SLOT_COUNT) {
    p.companions = [
      createDefaultCompanionSlot("Companion 1"),
      createDefaultCompanionSlot("Companion 2"),
      createDefaultCompanionSlot("Companion 3")
    ];
  }
  for (let i = 0; i < COMPANION_SLOT_COUNT; i++) {
    let c = p.companions[i];
    if (!c || typeof c !== "object") {
      c = createDefaultCompanionSlot(`Companion ${i + 1}`);
      p.companions[i] = c;
    }
    c = isolateCompanionProgressFromHero(p, c, i);
    if (c.classSkillLevels === p.classSkillLevels) {
      c.classSkillLevels = { ...p.classSkillLevels };
    }
    if (Array.isArray(c.skillBarSlots) && c.skillBarSlots === p.skillBarSlots) {
      c.skillBarSlots = p.skillBarSlots.slice();
    }
    const defaultName = `Companion ${i + 1}`;
    if (typeof c.enabled !== "boolean") c.enabled = false;
    if (typeof c.hasBeenEnabled !== "boolean") {
      c.hasBeenEnabled =
        !!c.enabled || !!(typeof c.name === "string" && c.name.trim() && c.name.trim() !== defaultName);
    }
    if (typeof c.name !== "string" || !c.name.trim()) c.name = defaultName;
    if (typeof c.level !== "number" || c.level < 1) c.level = 1;
    if (typeof c.xp !== "number" || !Number.isFinite(c.xp) || c.xp < 0) c.xp = 0;
    if (typeof c.allocPoolsCharV2 !== "boolean") c.allocPoolsCharV2 = false;
    if (typeof c.str !== "number") c.str = STAT_CHAR_ALLOC_FLOOR;
    if (typeof c.dex !== "number") {
      c.dex = typeof c.agi === "number" && Number.isFinite(c.agi) ? c.agi : STAT_CHAR_ALLOC_FLOOR;
    }
    if (Object.prototype.hasOwnProperty.call(c, "agi")) delete c.agi;
    if (typeof c.vit !== "number") c.vit = STAT_CHAR_ALLOC_FLOOR;
    if (typeof c.int !== "number") c.int = STAT_CHAR_ALLOC_FLOOR;
    if (typeof c.baseAttack !== "number") c.baseAttack = 10;
    if (typeof c.charPoints !== "number" || c.charPoints < 0) c.charPoints = 0;
    if (typeof c.skillPoints !== "number" || c.skillPoints < 0) c.skillPoints = 0;
    if (!c.classId || typeof c.classId !== "string") c.classId = DEFAULT_CLASS_ID;
    if (!c.classSkillLevels || typeof c.classSkillLevels !== "object") c.classSkillLevels = {};
    if (!Array.isArray(c.skills)) c.skills = [];
    syncPlayerClassSkillList(c);
    ensureActorSkillBar(c);
    normalizeActorProfessions(c);
    ensureActorProfessionProgress(c);
    if (!c.equipment || typeof c.equipment !== "object") c.equipment = emptyEquipment();
    if (!c.hasBeenEnabled && c.equipment && !c.equipment.weapon && !c.equipment.chest && !c.equipment.legs) {
      equipStarterGearIfEmpty(c);
    }
    enforceOffhandRuleForEquipment(c.equipment, p.inventory);
    if (typeof c.portraitGender !== "string" || !c.portraitGender.trim()) c.portraitGender = "male";
    ensurePortraitLayoutsStoreForOwner(c);
    if (c.portraitLayout && typeof c.portraitLayout === "object" && Object.keys(c.portraitLayout).length) {
      Object.assign(c.portraitLayouts.male.equipment, c.portraitLayout);
    }
    if (c.portraitBaseLayout && typeof c.portraitBaseLayout === "object") {
      c.portraitLayouts.male.base = c.portraitBaseLayout;
    }
    if (!c.allocPoolsBindToLevelV2) {
      c.allocPoolsBindToLevelV2 = true;
    }
    recomputeAllocPoolsFromLevel(c);
    levelUpActor(c);
    c.maxHp = computeMaxHp(c);
    if (typeof c.hp !== "number" || !Number.isFinite(c.hp)) c.hp = c.maxHp;
    c.hp = Math.min(c.maxHp, Math.max(1, c.hp));
  }
}

function getCharacterRosterTab() {
  return typeof characterPanelRosterTab === "string" && characterPanelRosterTab ? characterPanelRosterTab : "hero";
}

function getRosterActorFromTab(tab) {
  const t = tab || "hero";
  if (t === "hero") return player;
  const idx = parseInt(t, 10);
  if (Number.isFinite(idx) && idx >= 0 && idx < COMPANION_SLOT_COUNT && player && Array.isArray(player.companions)) {
    const c = player.companions[idx];
    if (c && typeof c === "object" && c !== player) return c;
  }
  return player;
}

function getActiveRosterActor() {
  return getRosterActorFromTab(getCharacterRosterTab());
}

function completeCompanionFirstEnable(slotIdx, rawName, gender) {
  ensurePlayerCompanions(player);
  if (!Number.isFinite(slotIdx) || slotIdx < 0 || slotIdx >= COMPANION_SLOT_COUNT) return false;
  const comp = player.companions && player.companions[slotIdx];
  if (!comp) return false;
  const nextName = typeof rawName === "string" ? rawName.trim().slice(0, 32) : "";
  if (!nextName) return false;
  comp.name = nextName;
  comp.portraitGender = normalizePortraitGender(gender);
  comp.hasBeenEnabled = true;
  ensurePortraitLayoutsStoreForOwner(comp);
  equipStarterGearIfEmpty(comp);
  comp.maxHp = computeMaxHp(comp);
  comp.hp = comp.maxHp;
  comp.enabled = true;
  save();
  closeModal();
  render();
  return true;
}

function buildCharacterCreationModalHtml(opts) {
  const o = opts && typeof opts === "object" ? opts : {};
  const mode = o.mode === "companion" ? "companion" : "hero";
  const slotIdx = typeof o.slotIdx === "number" ? o.slotIdx : 0;
  const g = normalizePortraitGender(o.selectedGender);
  const fallbackName = mode === "companion" ? `Companion ${slotIdx + 1}` : "Hero";
  const maleCls = g === "male" ? " companion-create-gender-btn--active" : "";
  const femaleCls = g === "female" ? " companion-create-gender-btn--active" : "";
  const err =
    o.errorMsg && String(o.errorMsg).trim()
      ? `<p class="companion-create-error">${escapeHtml(String(o.errorMsg).trim())}</p>`
      : "";
  const nameAttr = typeof o.nameValue === "string" ? escapeAttr(o.nameValue) : "";
  const title = mode === "companion" ? "Character creation" : "Create character";
  const lead =
    mode === "companion"
      ? "Set how this companion looks and what they are called. These choices are permanent."
      : "Choose your hero's name and appearance. These choices are permanent.";
  const confirmLabel = mode === "companion" ? "Create companion" : "Create character";
  const genderAttr = mode === "companion" ? "data-companion-create-gender" : "data-hero-create-gender";
  const confirmAttr = mode === "companion" ? "data-companion-name-confirm" : "data-hero-name-confirm";
  const cancelAttr = mode === "companion" ? "data-companion-name-cancel" : "data-hero-name-cancel";
  return `<div class="companion-create-modal">
    <h3 class="companion-create-title">${escapeHtml(title)}</h3>
    <p class="companion-create-lead muted">${escapeHtml(lead)}</p>
    ${err}
    <div class="companion-create-gender" role="radiogroup" aria-label="Body type">
      <button type="button" class="companion-create-gender-btn${maleCls}" ${genderAttr}="male" aria-pressed="${g === "male"}">
        <span class="companion-create-preview-wrap"><img src="Assets/Character/male_template.png" alt="" class="companion-create-preview" draggable="false" /></span>
        <span>Male</span>
      </button>
      <button type="button" class="companion-create-gender-btn${femaleCls}" ${genderAttr}="female" aria-pressed="${g === "female"}">
        <span class="companion-create-preview-wrap"><img src="Assets/Character/female_character.png" alt="" class="companion-create-preview" draggable="false" /></span>
        <span>Female</span>
      </button>
    </div>
    <label class="companion-create-name-label" for="companion-create-name-input">Name</label>
    <input id="companion-create-name-input" type="text" class="companion-create-name-input" data-companion-name-input maxlength="32" placeholder="${escapeAttr(
      fallbackName
    )}" value="${nameAttr}" autocomplete="off" />
    <div class="npc-dialog-actions">
      <button type="button" class="btn-primary" ${confirmAttr}>${escapeHtml(confirmLabel)}</button>
      <button type="button" class="btn-secondary" ${cancelAttr}>Cancel</button>
    </div>
  </div>`;
}

function buildCompanionCreationModalHtml(slotIdx, selectedGender, errorMsg, nameValue) {
  return buildCharacterCreationModalHtml({
    mode: "companion",
    slotIdx,
    selectedGender,
    errorMsg,
    nameValue
  });
}

function isHeroCreationModalOpen() {
  return pendingHeroCreationSlot != null && Number.isFinite(pendingHeroCreationSlot);
}

function isCharacterCreationModalOpen() {
  return isCompanionCreationModalOpen() || isHeroCreationModalOpen();
}

function isCompanionCreationModalOpen() {
  return pendingCompanionEnableSlot != null && Number.isFinite(pendingCompanionEnableSlot);
}

function openCompanionFirstEnableModal(slotIdx) {
  pendingCompanionEnableSlot = slotIdx;
  pendingCompanionCreationGender = "male";
  showModalHtml(buildCompanionCreationModalHtml(slotIdx, pendingCompanionCreationGender), { companionCreation: true });
  setTimeout(() => {
    const input = document.querySelector("[data-companion-name-input]");
    if (input && typeof input.focus === "function") input.focus();
  }, 0);
}

function refreshCompanionCreationModal(errorMsg) {
  const slotIdx = pendingCompanionEnableSlot;
  if (!Number.isFinite(slotIdx) || slotIdx < 0) return;
  const input = document.querySelector("[data-companion-name-input]");
  const nameValue = input && typeof input.value === "string" ? input.value : "";
  showModalHtml(buildCompanionCreationModalHtml(slotIdx, pendingCompanionCreationGender, errorMsg, nameValue), {
    companionCreation: true
  });
  setTimeout(() => {
    const next = document.querySelector("[data-companion-name-input]");
    if (next && typeof next.focus === "function") next.focus();
  }, 0);
}


function openHeroCreationModal(slotIdx) {
  pendingHeroCreationSlot = slotIdx;
  pendingHeroCreationGender = "male";
  showModalHtml(
    buildCharacterCreationModalHtml({
      mode: "hero",
      slotIdx,
      selectedGender: pendingHeroCreationGender
    }),
    { companionCreation: true }
  );
  setTimeout(() => {
    const input = document.querySelector("[data-companion-name-input]");
    if (input && typeof input.focus === "function") input.focus();
  }, 0);
}

function refreshHeroCreationModal(errorMsg) {
  const slotIdx = pendingHeroCreationSlot;
  if (!Number.isFinite(slotIdx) || slotIdx < 0) return;
  const input = document.querySelector("[data-companion-name-input]");
  const nameValue = input && typeof input.value === "string" ? input.value : "";
  showModalHtml(
    buildCharacterCreationModalHtml({
      mode: "hero",
      slotIdx,
      selectedGender: pendingHeroCreationGender,
      errorMsg,
      nameValue
    }),
    { companionCreation: true }
  );
  setTimeout(() => {
    const next = document.querySelector("[data-companion-name-input]");
    if (next && typeof next.focus === "function") next.focus();
  }, 0);
}

function normalizeCharacterNameKey(rawName) {
  return String(rawName || "").trim().toLowerCase();
}

function isCharacterNameTaken(rawName, exceptSlotIdx) {
  ensureCharacterRoster();
  const key = normalizeCharacterNameKey(rawName);
  if (!key) return true;
  for (let i = 0; i < CHARACTER_SLOT_COUNT; i++) {
    if (exceptSlotIdx != null && i === exceptSlotIdx) continue;
    const slot = characterRoster.slots[i];
    if (slot && normalizeCharacterNameKey(slot.name) === key) return true;
  }
  return false;
}

function emptyCharacterRoster() {
  return { version: 1, slots: Array.from({ length: CHARACTER_SLOT_COUNT }, () => null) };
}

function hydrateRosterSlot(raw) {
  if (!raw || typeof raw !== "object") return null;
  try {
    migratePlayer(raw);
    return raw;
  } catch {
    const salvage = salvagePlayerFromRaw(raw);
    try {
      migratePlayer(salvage);
    } catch {
      /* Keep salvaged raw state as a last resort. */
    }
    return salvage;
  }
}

function parseRosterJson(raw) {
  if (!raw) return null;
  try {
    const parsed = typeof raw === "string" ? JSON.parse(raw) : raw;
    if (!parsed || !Array.isArray(parsed.slots)) return null;
    const slots = parsed.slots.slice(0, CHARACTER_SLOT_COUNT);
    while (slots.length < CHARACTER_SLOT_COUNT) slots.push(null);
    return {
      version: 1,
      slots: slots.map((entry) => hydrateRosterSlot(entry))
    };
  } catch {
    return null;
  }
}

function rosterHasCharacters(roster) {
  return !!(roster && Array.isArray(roster.slots) && roster.slots.some(Boolean));
}

function loadRosterJsonFromLocalStorageCandidates() {
  const keys = [CHARACTER_ROSTER_KEY];
  try {
    const email =
      typeof window !== "undefined" && window.GameStorage && typeof window.GameStorage.getAuthEmail === "function"
        ? window.GameStorage.getAuthEmail()
        : "";
    if (email) keys.unshift(`${CHARACTER_ROSTER_KEY}:${email}`);
  } catch {
    /* ignore */
  }
  for (const key of keys) {
    try {
      const raw = localStorage.getItem(key);
      const roster = parseRosterJson(raw);
      if (rosterHasCharacters(roster)) return roster;
    } catch {
      /* try next key */
    }
  }
  return null;
}

async function migrateLegacyPlayerToRoster() {
  const fromLocal = loadRosterJsonFromLocalStorageCandidates();
  if (fromLocal) {
    characterRoster = fromLocal;
    await persistCharacterRoster();
    return fromLocal;
  }
  const roster = emptyCharacterRoster();
  const fromPrimary = parseSavedPlayerJson(localStorage.getItem(PLAYER_SAVE_KEY));
  const fromBackup = parseSavedPlayerJson(localStorage.getItem(PLAYER_SAVE_BACKUP_KEY));
  const legacy = fromPrimary || fromBackup;
  if (legacy) {
    roster.slots[0] = hydrateRosterSlot(legacy);
    characterRoster = roster;
    await persistCharacterRoster();
  }
  return roster;
}

async function loadCharacterRoster() {
  if (typeof window === "undefined" || !window.GameStorage) return emptyCharacterRoster();
  try {
    const raw = await window.GameStorage.loadRosterJson();
    const parsedRoster = parseRosterJson(raw);
    if (rosterHasCharacters(parsedRoster)) return parsedRoster;
  } catch (err) {
    console.error("Failed to load roster from server:", err);
  }
  // One-time upload if the account has no server roster yet but legacy browser saves exist.
  return migrateLegacyPlayerToRoster();
}

/** Apply server-validated roster JSON (online Phase 3). */
function applyAuthoritativeRosterJson(json, options) {
  if (!json || typeof json !== "string") return;
  const noRender = !!(options && options.noRender);
  try {
    const parsed = JSON.parse(json);
    if (!parsed || !Array.isArray(parsed.slots)) return;
    const slots = parsed.slots.slice(0, CHARACTER_SLOT_COUNT);
    while (slots.length < CHARACTER_SLOT_COUNT) slots.push(null);
    characterRoster = {
      version: 1,
      slots: slots.map((entry) => hydrateRosterSlot(entry))
    };
    if (inGameSession && activeCharacterSlotIndex != null && characterRoster.slots[activeCharacterSlotIndex]) {
      player = characterRoster.slots[activeCharacterSlotIndex];
      migratePlayer(player);
    }
    if (noRender) {
      if (inGameSession && currentPage === "adventure") syncMinimapSlots();
      return;
    }
    if (!inGameSession) renderCharacterSelectScreen();
    else if (currentPage === "adventure") syncMinimapSlots();
    else render();
  } catch {
    /* ignore */
  }
}
if (typeof window !== "undefined") window.applyAuthoritativeRosterJson = applyAuthoritativeRosterJson;

function isOnlineGameplayMode() {
  return (
    typeof window !== "undefined" &&
    window.GameStorage &&
    typeof window.GameStorage.isOnlineMode === "function" &&
    window.GameStorage.isOnlineMode()
  );
}

function canPerformServerPlayerAction() {
  return isOnlineGameplayMode() && inGameSession && activeCharacterSlotIndex != null && !!window.GameStorage;
}

function showServerActionRequired(message) {
  showModal(message || "Log in and select a character to perform this action.");
}

function resolveOnlineTargetFromActor(actor) {
  if (!actor || actor === player) return { target: "hero", companionSlotIndex: null };
  if (player && Array.isArray(player.companions)) {
    const idx = player.companions.indexOf(actor);
    if (idx >= 0) return { target: "companion", companionSlotIndex: idx };
  }
  return { target: "hero", companionSlotIndex: null };
}

async function applyOnlineActionResponse(body, options) {
  if (!body || !body.roster) return false;
  if (
    body.revision != null &&
    typeof window !== "undefined" &&
    window.GameStorage &&
    typeof window.GameStorage.setRosterRevision === "function"
  ) {
    window.GameStorage.setRosterRevision(body.revision);
  }
  applyAuthoritativeRosterJson(JSON.stringify(body.roster), { noRender: !!(options && options.noRender) });
  if (!(options && options.noRender)) render();
  return true;
}

/** Cached server feature status for arena / market / alliance panels (Phase C). */
let mmoFeatureCatalog = null;

async function ensureMmoFeatureCatalog() {
  if (!isOnlineGameplayMode() || !window.GameStorage?.fetchMmoFeatures) return null;
  try {
    mmoFeatureCatalog = await window.GameStorage.fetchMmoFeatures(false);
  } catch {
    mmoFeatureCatalog = null;
  }
  return mmoFeatureCatalog;
}

async function commitWorldMapPositionOnline(nx, ny, reason) {
  if (activeCharacterSlotIndex == null || !window.GameStorage?.worldMove) return false;
  try {
    const body = await window.GameStorage.worldMove({
      slotIndex: activeCharacterSlotIndex,
      x: nx,
      y: ny,
      reason: reason || "step"
    });
    await applyOnlineActionResponse(body);
    publishOnlinePresenceNow();
    return true;
  } catch (err) {
    console.error("worldMove:", err);
    showModal(err && err.message ? err.message : "Could not move.");
    return false;
  }
}

async function commitWorldMapPosition(nx, ny, reason) {
  return commitWorldMapPositionOnline(nx, ny, reason);
}

/** Apply server-merged world map from a saved roster JSON; keep local mob preview caches. */
function syncPlayerWorldMapFromSavedRoster(savedJson) {
  if (!savedJson || !inGameSession || activeCharacterSlotIndex == null || !player) return;
  try {
    const parsed = JSON.parse(savedJson);
    const slot = parsed?.slots?.[activeCharacterSlotIndex];
    if (!slot?.worldMap || typeof slot.worldMap !== "object") return;
    const localCells =
      player.worldMap && typeof player.worldMap.cells === "object" ? player.worldMap.cells : {};
    const serverWm = slot.worldMap;
    player.worldMap = {
      ...player.worldMap,
      ...serverWm,
      cells: serverWm.cells && typeof serverWm.cells === "object" ? { ...serverWm.cells } : {}
    };
    Object.keys(localCells).forEach((k) => {
      const loc = localCells[k];
      const merged = player.worldMap.cells[k];
      if (loc && merged && Array.isArray(loc.mobPreviews)) {
        player.worldMap.cells[k] = { ...merged, mobPreviews: loc.mobPreviews };
      }
    });
    migratePlayer(player);
    ensureCharacterRoster();
    characterRoster.slots[activeCharacterSlotIndex] = player;
  } catch {
    /* ignore */
  }
}

/** Serializes online roster PUTs so stale responses cannot rewind world-map position. */
let rosterPersistChain = Promise.resolve();
let rosterPersistInFlight = false;

async function persistCharacterRoster() {
  if (!characterRoster) return;
  if (rosterPersistInFlight) return;
  if (
    typeof window !== "undefined" &&
    window.ServerCombat &&
    typeof window.ServerCombat.hasSession === "function" &&
    window.ServerCombat.hasSession()
  ) {
    return;
  }
  if (inGameSession && activeCharacterSlotIndex != null && player) {
    ensureCharacterRoster();
    characterRoster.slots[activeCharacterSlotIndex] = player;
  }
  const json = JSON.stringify(characterRoster);
  if (typeof window !== "undefined" && window.GameStorage) {
    rosterPersistChain = rosterPersistChain.then(async () => {
      rosterPersistInFlight = true;
      try {
        const result = await window.GameStorage.saveRosterJson(json);
        const saved =
          result && typeof result === "object" && result.rosterJson != null
            ? result.rosterJson
            : typeof result === "string"
              ? result
              : json;
        syncPlayerWorldMapFromSavedRoster(saved);
      } catch (err) {
        console.error("Failed to save roster to server:", err);
      } finally {
        rosterPersistInFlight = false;
      }
    });
    await rosterPersistChain;
  }
}

function ensureCharacterRoster() {
  if (!characterRoster || !Array.isArray(characterRoster.slots)) {
    characterRoster = emptyCharacterRoster();
  }
}

