function buildCraftInviteCrafterPickHtml() {
  if (!player) return "";
  const parts = [`<label class="craft-invite-crafter-label">Crafter</label>`];
  parts.push(
    `<label class="craft-invite-crafter-option"><input type="radio" name="craftInviteCrafter" value="hero" checked /> ${escapeHtml(player.name || "Hero")}</label>`
  );
  if (Array.isArray(player.companions)) {
    player.companions.forEach((c, i) => {
      if (!c || !c.enabled) return;
      parts.push(
        `<label class="craft-invite-crafter-option"><input type="radio" name="craftInviteCrafter" value="c${i}" /> ${escapeHtml(c.name || `Companion ${i + 1}`)}</label>`
      );
    });
  }
  return `<div class="craft-invite-crafter-options">${parts.join("")}</div>`;
}

function showCraftCommissionRequestModal(targetUserId, targetName) {
  const recipes = getAllCraftingRecipes().slice().sort((a, b) => {
    const aLvl = typeof a.resultLevel === "number" ? a.resultLevel : 1;
    const bLvl = typeof b.resultLevel === "number" ? b.resultLevel : 1;
    return aLvl - bLvl || String(a.resultItem || "").localeCompare(String(b.resultItem || ""));
  });
  const options = recipes
    .map((r) => {
      const profId = getCraftingProfessionIdForRecipe(r);
      return `<option value="${escapeAttr(r.id || "")}">${escapeHtml(r.resultItem || r.id)} (${escapeHtml(getProfessionLabel(profId))}, lv ${typeof r.resultLevel === "number" ? r.resultLevel : 1})</option>`;
    })
    .join("");
  showModalHtml(
    `<div class="craft-commission-request">
      <h3 class="modal-compact-title">Invite ${escapeHtml(targetName || "player")} to craft</h3>
      <p class="muted">You supply ingredients and gold; they craft into your inventory.</p>
      <label class="craft-commission-field">Recipe<select id="craftCommissionRecipe" class="craft-commission-select">${options}</select></label>
      <label class="craft-commission-field">Quantity<input id="craftCommissionQty" type="number" min="1" max="999" value="1" class="craft-commission-input" /></label>
      <label class="craft-commission-field">Gold offer<input id="craftCommissionGold" type="number" min="0" value="0" class="craft-commission-input" /></label>
      <p class="muted">Your gold: ${player?.gold || 0}</p>
      <div class="modal-compact-actions">
        <button type="button" class="btn-primary" id="craftCommissionSendBtn">Send invite</button>
        <button type="button" class="btn-secondary" onclick="closeModal()">Cancel</button>
      </div>
    </div>`
  );
  setTimeout(() => {
    const sendBtn = document.getElementById("craftCommissionSendBtn");
    if (!sendBtn || sendBtn.dataset.bound === "1") return;
    sendBtn.dataset.bound = "1";
    sendBtn.addEventListener("click", () => {
      const recipeEl = document.getElementById("craftCommissionRecipe");
      const qtyEl = document.getElementById("craftCommissionQty");
      const goldEl = document.getElementById("craftCommissionGold");
      const recipeId = recipeEl && recipeEl.value ? recipeEl.value : "";
      const quantity = qtyEl ? Math.max(1, Math.min(999, Math.floor(Number(qtyEl.value) || 1))) : 1;
      const goldOffer = goldEl ? Math.max(0, Math.floor(Number(goldEl.value) || 0)) : 0;
      if (!recipeId) return;
      if (window.MMOPresence?.sendCraftInvite) {
        window.MMOPresence.sendCraftInvite({
          targetUserId,
          requesterSlotIndex: activeCharacterSlotIndex,
          recipeId,
          quantity,
          goldOffer
        });
      }
      closeModal();
      hideMapPlayerActions();
    });
  }, 0);
}

function showFightInviteModal(payload) {
  pendingFightInvitePayload = payload;
  if (typeof window !== "undefined") window.pendingFightInvitePayload = payload;
  const modal = document.getElementById("fightInviteModal");
  const text = document.getElementById("fightInviteText");
    if (text) {
    const secs =
      payload.prepEndsAt && payload.prepEndsAt > Date.now()
        ? Math.ceil((payload.prepEndsAt - Date.now()) / 1000)
        : 30;
    text.textContent = `${payload.hostName || "A party member"} started a fight on this tile. Party members here can join during preparation (${secs}s).`;
  }
  if (modal) modal.classList.remove("hidden");
}

function hideFightInviteModal() {
  const modal = document.getElementById("fightInviteModal");
  if (modal) modal.classList.add("hidden");
  pendingFightInvitePayload = null;
  if (typeof window !== "undefined") window.pendingFightInvitePayload = null;
}

function notifyPartyOfFightStart(region, mob, worldMapContext) {
  if (typeof window === "undefined" || !window.MMOPresence?.publishPartyFightStarted) return;
  const units = mob?.units ? mob.units : null;
  window.MMOPresence.publishPartyFightStarted({
    region: region ? { name: region.name, enemyScale: region.enemyScale } : null,
    mob: units ? { units: units.map((u) => ({ ...u })) } : mob,
    worldMapContext: worldMapContext || null
  });
}

function bindAdventureCampFightHandlers(_root) {
  const host = document.getElementById("content");
  if (!host || host.dataset.campFightBound === "1") return;
  host.dataset.campFightBound = "1";
  host.addEventListener("click", (e) => {
    const camp = e.target.closest(".world-camp[data-world-fight].world-camp--ready");
    if (!camp || !host.contains(camp)) return;
    const si = parseInt(camp.getAttribute("data-world-fight"), 10);
    if (!Number.isNaN(si)) startWorldMapFight(si);
  });
}

function buildWorldCampTipPayload(preview, pool, si) {
  if (preview && preview.units && preview.units.length) {
    return {
      kind: "units",
      tier: preview.difficultyTier || MOB_DIFFICULTY_TIER_LABELS[si % 3],
      totalLevel:
        typeof preview.mobTotalLevel === "number"
          ? preview.mobTotalLevel
          : preview.units.reduce((s, u) => s + (typeof u.level === "number" ? u.level : 0), 0),
      units: preview.units.map((u) => ({ name: u.name, level: u.level, mood: u.moodName }))
    };
  }
  return { kind: "pool", pool: pool.slice(), min: MOB_SIZE_MIN, max: MOB_SIZE_MAX };
}

function buildWorldCampEncounterCellHtml(si, preview, pool, posStyleAttr) {
  const tipPayload = buildWorldCampTipPayload(preview, pool, si);
  const campPayload = escapeAttr(JSON.stringify(tipPayload));
  const hasUnits = !!(preview && preview.units && preview.units.length);
  const thumbsActive = hasUnits ? buildWorldCampMobThumbsHtmlFromUnits(preview.units) : "";
  const ariaTier = hasUnits ? preview.difficultyTier || MOB_DIFFICULTY_TIER_LABELS[si % 3] : "encounter";
  const pendingUi = hasUnits ? "" : `<span class="world-camp-loading muted">Loading encounter…</span>`;
  const readyCls = hasUnits ? " world-camp--ready" : " world-camp--pending";
  return `<div class="mob-cell world-camp${readyCls}" data-world-camp="${si}" data-camp-enemies="${campPayload}"${
    hasUnits ? ` data-world-fight="${si}"` : ""
  } aria-label="${escapeAttr(`${ariaTier} encounter ${si + 1}`)}"${posStyleAttr || ""}>
        <div class="mob-imgs mob-imgs--world">${thumbsActive}</div>
        ${pendingUi}
      </div>`;
}

function buildWorldCampCellHtml(x, y, si, pool, posStyleAttr) {
  if (slotIsWorldMobOnRespawnCooldown(x, y, si)) return "";
  const preview = ensureMobPreview(x, y, si);
  return buildWorldCampEncounterCellHtml(si, preview, pool, posStyleAttr);
}

function tileNeedsServerMobPreviews(x, y) {
  const cellCfg = getCoordinateCellConfig(x, y);
  if (cellCfg.kind !== "encounters") return false;
  const encounterSlots = getEncounterSlotCountForCell(x, y, cellCfg);
  const key = worldMapKey(x, y);
  const rec = player?.worldMap?.cells?.[key];
  for (let si = 0; si < encounterSlots; si++) {
    if (slotIsWorldMobOnRespawnCooldown(x, y, si)) continue;
    const pv = rec?.mobPreviews?.[si];
    if (!pv || !Array.isArray(pv.units) || !pv.units.length) return true;
  }
  return false;
}

function getWorldCampRenderSignature(x, y, encounterSlots) {
  const parts = [];
  for (let si = 0; si < encounterSlots; si++) {
    if (slotIsWorldMobOnRespawnCooldown(x, y, si)) {
      parts.push(`${si}:cd`);
      continue;
    }
    const preview = ensureMobPreview(x, y, si);
    if (preview && preview.units && preview.units.length) {
      parts.push(
        `${si}:u:${preview.units.map((u) => `${u.name}@${u.level}`).join(",")}`
      );
    } else {
      parts.push(`${si}:pending`);
    }
  }
  return `${x},${y}|${parts.join(";")}`;
}

/** After map_cell sync, rebuild encounter panels with server mob previews (online). */
function scheduleAdventureEncountersRefreshFromServer() {
  if (typeof window === "undefined" || !window.GameStorage?.isOnlineMode?.() || !window.MMOPresence) return;
  if (currentPage !== "adventure" || !player?.worldMap) return;
  const x = player.worldMap.x;
  const y = player.worldMap.y;
  const cellCfg = getCoordinateCellConfig(x, y);
  if (cellCfg.kind !== "encounters") return;
  const key = worldMapKey(x, y);
  const cached = window.MMOPresence.getMapCellCache?.(key);
  if (cached) applySharedMapCellFromServer(cached);
  if (!tileNeedsServerMobPreviews(x, y)) {
    refreshAdventureEncountersOnly();
    return;
  }
  window.MMOPresence.requestMapCellSync(x, y);
  if (!window.MMOPresence.waitForMapCell) return;
  window.MMOPresence.waitForMapCell(key, 5000).then((cell) => {
    if (!cell || currentPage !== "adventure" || !player?.worldMap) return;
    if (worldMapKey(player.worldMap.x, player.worldMap.y) !== key) return;
    applySharedMapCellFromServer(cell);
    refreshAdventureEncountersOnly();
  });
}

function refreshAdventureEncountersOnly() {
  if (currentPage !== "adventure" || !player?.worldMap) return;
  const x = player.worldMap.x;
  const y = player.worldMap.y;
  const root = document.getElementById("adventurePageRoot");
  const campsWrap = root?.querySelector(".world-camps");
  if (!campsWrap) {
    renderAdventure();
    return;
  }
  const dungeonRun = getActiveDungeonRun();
  if (dungeonRun || campsWrap.classList.contains("world-camps--scene")) {
    renderAdventure();
    return;
  }
  const key = worldMapKey(x, y);
  const cached = window.MMOPresence?.getMapCellCache?.(key);
  if (cached) applySharedMapCellFromServer(cached);
  syncSharedMapCellForTile(x, y);
  const biome = getWorldBiomeDefAt(x, y);
  const pool = biome.possibleEnemies || [];
  const cellCfg = getCoordinateCellConfig(x, y);
  if (!biome.passable || cellCfg.kind !== "encounters" || !pool.length) return;

  const encounterSlots = getEncounterSlotCountForCell(x, y, cellCfg);
  let campsHtml = "";
  let visibleCount = 0;
  for (let si = 0; si < encounterSlots; si++) {
    if (!slotIsWorldMobOnRespawnCooldown(x, y, si)) visibleCount++;
  }
  const campPosStyleForSlot = (si) => {
    const campPos = getCachedCampPanelPositions(x, y, encounterSlots);
    const p = campPos[si];
    return p ? ` style="left:${p.leftPct}%;top:${p.topPct}%;transform:translate(-50%,-50%);"` : "";
  };
  for (let si = 0; si < encounterSlots; si++) {
    campsHtml += buildWorldCampCellHtml(x, y, si, pool, campPosStyleForSlot(si));
  }
  if (visibleCount > 0) {
    const sig = getWorldCampRenderSignature(x, y, encounterSlots);
    if (campsWrap.dataset.campSig === sig) {
      applyWorldCampPositionsToDom();
      return;
    }
    campsWrap.dataset.campSig = sig;
    campsWrap.className = "world-camps world-camps--spread world-camps--spread--ready";
    campsWrap.innerHTML = campsHtml;
    bindAdventureCampFightHandlers(root);
    applyWorldCampPositionsToDom();
    hydrateSpriteAnimations(root);
    if (!adventureCampWanderTick) startAdventureCampWanderTimer();
  } else {
    delete campsWrap.dataset.campSig;
    campsHtml = "";
    campsWrap.className = "world-camps";
    campsWrap.innerHTML = campsHtml;
    clearAdventureCampWanderTimer();
  }
}

function initMapPlayersPanelUi() {
  const list = document.getElementById("mapPlayersList");
  if (list && list.dataset.bound !== "1") {
    list.dataset.bound = "1";
    list.addEventListener("click", (e) => {
      const row = e.target.closest("[data-map-player-name]");
      if (!row || row.classList.contains("map-players-item--you")) return;
      const userId = parseInt(row.getAttribute("data-map-player-id"), 10);
      const name = row.getAttribute("data-map-player-name") || "";
      if (Number.isFinite(userId)) showMapPlayerActions(userId, name);
    });
  }
  const inviteBtn = document.getElementById("mapPlayerPartyInviteBtn");
  if (inviteBtn && inviteBtn.dataset.bound !== "1") {
    inviteBtn.dataset.bound = "1";
    inviteBtn.addEventListener("click", () => {
      if (!mapPlayerActionTarget) return;
      if (window.MMOPresence?.sendPartyInvite) {
        window.MMOPresence.sendPartyInvite({
          targetUserId: mapPlayerActionTarget.userId,
          targetName: mapPlayerActionTarget.name
        });
        if (window.MMOChat?.appendSystem) {
          window.MMOChat.appendSystem(`Party invite sent to ${mapPlayerActionTarget.name}.`);
        }
      }
    });
  }
  const craftInviteBtn = document.getElementById("mapPlayerCraftInviteBtn");
  if (craftInviteBtn && craftInviteBtn.dataset.bound !== "1") {
    craftInviteBtn.dataset.bound = "1";
    craftInviteBtn.addEventListener("click", () => {
      if (!mapPlayerActionTarget) return;
      if (!isOnlineGameplayMode()) {
        showServerActionRequired("Commission crafting requires a server connection.");
        return;
      }
      showCraftCommissionRequestModal(mapPlayerActionTarget.userId, mapPlayerActionTarget.name);
    });
  }
  const tradeBtn = document.getElementById("mapPlayerTradeBtn");
  if (tradeBtn && tradeBtn.dataset.bound !== "1") {
    tradeBtn.dataset.bound = "1";
    tradeBtn.addEventListener("click", () => {
      if (!mapPlayerActionTarget) return;
      if (!isOnlineGameplayMode()) {
        showServerActionRequired("Trading requires a server connection.");
        return;
      }
      if (window.MMOPresence?.sendTradeRequest) {
        window.MMOPresence.sendTradeRequest(mapPlayerActionTarget.userId);
        hideMapPlayerActions();
      }
    });
  }
  const msgBtn = document.getElementById("mapPlayerMessageBtn");
  if (msgBtn && msgBtn.dataset.bound !== "1") {
    msgBtn.dataset.bound = "1";
    msgBtn.addEventListener("click", () => {
      if (!mapPlayerActionTarget) return;
      if (window.MMOChat?.startPrivateMessage) window.MMOChat.startPrivateMessage(mapPlayerActionTarget.name);
    });
  }
  const closeBtn = document.getElementById("mapPlayerActionsClose");
  if (closeBtn && closeBtn.dataset.bound !== "1") {
    closeBtn.dataset.bound = "1";
    closeBtn.addEventListener("click", () => hideMapPlayerActions());
  }
  if (document.documentElement.dataset.mapPlayerActionsEscBound !== "1") {
    document.documentElement.dataset.mapPlayerActionsEscBound = "1";
    document.addEventListener("keydown", (e) => {
      if (e.key !== "Escape") return;
      const panel = document.getElementById("mapPlayerActions");
      if (panel && !panel.classList.contains("hidden")) hideMapPlayerActions();
    });
  }
  const partyAccept = document.getElementById("partyInviteAcceptBtn");
  if (partyAccept && partyAccept.dataset.bound !== "1") {
    partyAccept.dataset.bound = "1";
    partyAccept.addEventListener("click", () => {
      if (window.MMOPresence?.acceptPartyInvite) window.MMOPresence.acceptPartyInvite();
      hidePartyInviteModal();
    });
  }
  const partyDecline = document.getElementById("partyInviteDeclineBtn");
  if (partyDecline && partyDecline.dataset.bound !== "1") {
    partyDecline.dataset.bound = "1";
    partyDecline.addEventListener("click", () => {
      if (window.MMOPresence?.declinePartyInvite) window.MMOPresence.declinePartyInvite();
      hidePartyInviteModal();
    });
  }
  const craftAccept = document.getElementById("craftInviteAcceptBtn");
  if (craftAccept && craftAccept.dataset.bound !== "1") {
    craftAccept.dataset.bound = "1";
    craftAccept.addEventListener("click", () => {
      let crafterTarget = "hero";
      let companionSlotIndex = null;
      const picked = document.querySelector('input[name="craftInviteCrafter"]:checked');
      if (picked && typeof picked.value === "string" && picked.value.startsWith("c")) {
        crafterTarget = "companion";
        companionSlotIndex = parseInt(picked.value.slice(1), 10);
      }
      if (window.MMOPresence?.acceptCraftInvite) {
        window.MMOPresence.acceptCraftInvite({ crafterTarget, companionSlotIndex });
      }
      hideCraftInviteModal();
    });
  }
  const craftDecline = document.getElementById("craftInviteDeclineBtn");
  if (craftDecline && craftDecline.dataset.bound !== "1") {
    craftDecline.dataset.bound = "1";
    craftDecline.addEventListener("click", () => {
      if (window.MMOPresence?.declineCraftInvite) window.MMOPresence.declineCraftInvite();
      hideCraftInviteModal();
    });
  }
  const fightJoin = document.getElementById("fightInviteJoinBtn");
  if (fightJoin && fightJoin.dataset.bound !== "1") {
    fightJoin.dataset.bound = "1";
    fightJoin.addEventListener("click", async () => {
      let payload = pendingFightInvitePayload;
      hideFightInviteModal();
      if (isFightOverlayOpen()) return;
      if ((!payload || !payload.sessionId) && window.ServerCombat?.fetchPartySession) {
        const open = await window.ServerCombat.fetchPartySession();
        if (open?.sessionId) {
          payload = {
            sessionId: open.sessionId,
            hostName: "Party member",
            region: { name: "Encounter", enemyScale: 1 },
            mob: { units: [] },
            worldMapContext: null
          };
        }
      }
      if (!payload) return;
      const region = payload.region || { name: "Encounter", enemyScale: 1 };
      const mob = payload.mob || { units: [] };
      await beginTurnCombat(
        region,
        mob,
        payload.worldMapContext || null,
        payload.sessionId || null
      );
    });
  }
  const fightDecline = document.getElementById("fightInviteDeclineBtn");
  if (fightDecline && fightDecline.dataset.bound !== "1") {
    fightDecline.dataset.bound = "1";
    fightDecline.addEventListener("click", () => hideFightInviteModal());
  }
}

function initOnlinePresence() {
  if (typeof window === "undefined" || !window.MMOPresence || !window.GameStorage?.isOnlineMode()) return;
  window.MMOPresence.setStateProvider(getPresenceStateForClient);
  window.onMapCellUpdated = (mapCell) => {
    applySharedMapCellFromServer(mapCell);
    if (isFightOverlayOpen()) return;
    if (
      inGameSession &&
      currentPage === "adventure" &&
      player?.worldMap &&
      mapCell?.key === worldMapKey(player.worldMap.x, player.worldMap.y)
    ) {
      refreshAdventureEncountersOnly();
      hydrateSpriteAnimations(document.getElementById("adventurePageRoot"));
    }
  };
  window.onPresenceWelcome = () => {
    if (inGameSession && currentPage === "adventure" && player?.worldMap) {
      syncSharedMapCellForTile(player.worldMap.x, player.worldMap.y);
    }
  };
  window.onPartyInvite = (msg) => {
    if (msg && msg.fromName) {
      showPartyInviteModal(msg.fromName);
      if (window.MMOChat?.appendSystem) {
        window.MMOChat.appendSystem(`${msg.fromName} invited you to a party.`);
      }
    }
  };
  window.onPartyState = () => {
    updateMapPlayersPanel();
    syncMinimapSlots();
  };
  window.onDungeonEnterInvite = (msg) => {
    const text =
      msg && typeof msg.message === "string" && msg.message.trim()
        ? msg.message.trim()
        : "Your party is entering a dungeon. Meet at the entrance with your key.";
    showModal(text);
  };
  window.onPartyResult = (msg) => {
    if (!msg || !msg.message) return;
    if (window.MMOChat?.appendSystem) window.MMOChat.appendSystem(msg.message);
    if (!msg.ok && typeof showModal === "function") showModal(msg.message);
  };
  window.onCraftInvite = (msg) => {
    if (!msg) return;
    showCraftInviteModal(msg);
    if (window.MMOChat?.appendSystem) {
      window.MMOChat.appendSystem(`${msg.fromName || "A player"} sent a craft commission.`);
    }
  };
  window.onCraftResult = (msg) => {
    if (!msg || !msg.message) return;
    if (window.MMOChat?.appendSystem) window.MMOChat.appendSystem(msg.message);
    if (!msg.ok && typeof showModal === "function") showModal(msg.message);
  };
  window.onTradeInvite = (msg) => {
    if (!msg) return;
    if (window.MMOTrade?.showInvite) window.MMOTrade.showInvite(msg.fromName);
    if (window.MMOChat?.appendSystem) {
      window.MMOChat.appendSystem(`${msg.fromName || "A player"} wants to trade.`);
    }
  };
  window.onTradeResult = (msg) => {
    if (!msg || !msg.message) return;
    if (window.MMOChat?.appendSystem) window.MMOChat.appendSystem(msg.message);
    if (!msg.ok && typeof showModal === "function") showModal(msg.message);
  };
  window.onCraftCommissionComplete = async (msg) => {
    if (!msg || !msg.ok) return;
    if (msg.roster && typeof applyOnlineActionResponse === "function") {
      await applyOnlineActionResponse({ roster: msg.roster, revision: msg.revision });
    }
    const line =
      msg.role === "crafter"
        ? `Commission complete: crafted ${msg.quantity}× ${msg.recipeName} for ${msg.fromName}. +${msg.xpGained || 0} profession XP.`
        : `${msg.crafterName || "Crafter"} delivered ${msg.quantity}× ${msg.recipeName}.`;
    if (window.MMOChat?.appendSystem) window.MMOChat.appendSystem(line);
    render();
  };
  window.onFightInvite = (msg) => {
    if (!msg || !msg.sessionId) return;
    if (isFightOverlayOpen()) return;
    showFightInviteModal(msg);
    if (window.MMOChat?.appendSystem) {
      window.MMOChat.appendSystem(
        `${msg.hostName || "A party member"} started a fight nearby — open the invite to join.`
      );
    }
  };
  window.onCombatState = (msg) => {
    if (window.ServerCombat && typeof window.ServerCombat.applyRemoteCombatState === "function") {
      window.ServerCombat.applyRemoteCombatState(msg);
    }
  };
  window.onPresenceUpdated = () => {
    updateMapPlayersPanel();
    syncMinimapSlots();
  };
  window.MMOPresence.connect();
}

function publishOnlinePresenceNow() {
  if (typeof window !== "undefined" && window.MMOPresence && window.GameStorage?.isOnlineMode()) {
    window.MMOPresence.publishPresence();
  }
}

function updateMapPlayersPanel() {
  const panel = document.getElementById("mapPlayersPanel");
  if (!panel) return;
  const dungeonRun = getActiveDungeonRun();
  const show =
    inGameSession &&
    currentPage === "adventure" &&
    typeof window !== "undefined" &&
    window.GameStorage?.isOnlineMode?.();
  panel.classList.toggle("hidden", !show);
  document.documentElement.style.setProperty("--map-players-panel-width", show ? "188px" : "0px");

  if (!show || !player?.worldMap) return;
  const x = player.worldMap.x;
  const y = player.worldMap.y;
  const coordsEl = document.getElementById("mapPlayersCoords");
  const listEl = document.getElementById("mapPlayersList");
  const biome = getWorldBiomeDefAt(x, y);
  const defDg = dungeonRun && !dungeonRun.epilogue ? getDungeonDef(dungeonRun.id) : null;
  if (coordsEl) {
    if (defDg) {
      const ri = typeof dungeonRun.roomIndex === "number" ? dungeonRun.roomIndex + 1 : 1;
      const roomCount = Array.isArray(defDg.rooms) ? defDg.rooms.length : "?";
      coordsEl.textContent = `${defDg.name || dungeonRun.id} · Room ${ri}/${roomCount}`;
    } else {
      coordsEl.textContent = `[${x}, ${y}]${biome?.name ? ` · ${biome.name}` : ""}`;
    }
  }
  if (!listEl) return;
  const party = window.MMOPresence?.getParty?.();
  const locationLabel = defDg ? "In this chamber" : "On this tile";
  let html = "";
  if (party && Array.isArray(party.members) && party.members.length) {
    html += `<li class="map-players-section muted">Party</li>`;
    for (const m of party.members) {
      const isYou = m.name === (player.name || "You");
      html += `<li class="map-players-item${isYou ? " map-players-item--you" : ""}">${escapeHtml(m.name || "Traveler")}${isYou ? ' <span class="muted">(you)</span>' : ""}</li>`;
    }
    html += `<li class="map-players-section muted">${locationLabel}</li>`;
  }
  html += `<li class="map-players-item map-players-item--you">${escapeHtml(player.name || "You")} <span class="muted">(you)</span></li>`;
  const others = window.MMOPresence?.getSameMap?.() || [];
  if (others.length) {
    for (const p of others) {
      html += `<li class="map-players-item map-players-item--clickable" data-map-player-id="${p.userId}" data-map-player-name="${escapeAttr(p.name || "Traveler")}" role="button" tabindex="0">${escapeHtml(p.name || "Traveler")}</li>`;
    }
  } else {
    html += `<li class="map-players-item map-players-item--empty muted">No other players here</li>`;
  }
  listEl.innerHTML = html;
}

async function tryResumeOnlineCombat(slotIndex) {
  if (
    typeof window === "undefined" ||
    !window.GameStorage?.isOnlineMode?.() ||
    !window.ServerCombat ||
    typeof window.ServerCombat.resume !== "function"
  ) {
    return false;
  }
  try {
    return await window.ServerCombat.resume(slotIndex);
  } catch (err) {
    console.warn("tryResumeOnlineCombat:", err);
    return false;
  }
}

async function startGameWithSelectedCharacter() {
  ensureCharacterRoster();
  const idx = selectedCharacterSlotIndex;
  if (idx == null || !Number.isFinite(idx) || idx < 0 || idx >= CHARACTER_SLOT_COUNT) return;
  const slotPlayer = characterRoster.slots[idx];
  if (!slotPlayer) return;
  player = slotPlayer;
  activeCharacterSlotIndex = idx;
  inGameSession = true;
  syncPlayerSessionUi();
  initPlayerSession();
  initOnlinePresence();
  void ensureMmoFeatureCatalog();
  const resumed = await tryResumeOnlineCombat(idx);
  if (resumed) {
    setCharacterSelectScreenVisible(false);
    setGameSessionUiVisible(true);
    hideLoadingOverlay();
    return;
  }
  setCharacterSelectScreenVisible(false);
  setGameSessionUiVisible(true);
  showLoadingOverlay();
  render();
  waitForAllImagesToLoad().catch(() => hideLoadingOverlay());
}

function initEarlyModalUi() {
  const modalEl = document.getElementById("modal");
  if (!modalEl || modalEl.dataset.earlyUiBound === "1") return;
  modalEl.dataset.earlyUiBound = "1";
  modalEl.addEventListener("click", onPortalNetworkModalClick);
  modalEl.addEventListener("submit", (ev) => {
    const form = ev.target;
    if (!form || !form.matches || !form.matches("form[data-char-spend-form]")) return;
    ev.preventDefault();
    applyCharSpendFromModal();
  });
  modalEl.addEventListener("dblclick", onModalDblClick);
}

function onCharacterSelectScreenClick(e) {
  const screen = document.getElementById("characterSelectScreen");
  if (!screen || screen.classList.contains("hidden") || !screen.contains(e.target)) return;
  ensureCharacterRoster();
  const addBtn = e.target.closest("[data-character-slot-add]");
  if (addBtn && addBtn.dataset.characterSlotAdd != null && addBtn.dataset.characterSlotAdd !== "") {
    const si = parseInt(addBtn.dataset.characterSlotAdd, 10);
    if (Number.isFinite(si) && si >= 0 && si < CHARACTER_SLOT_COUNT && !characterRoster.slots[si]) {
      openHeroCreationModal(si);
    }
    return;
  }
  const pickBtn = e.target.closest("[data-character-slot-select]");
  if (pickBtn && pickBtn.dataset.characterSlotSelect != null && pickBtn.dataset.characterSlotSelect !== "") {
    const si = parseInt(pickBtn.dataset.characterSlotSelect, 10);
    if (Number.isFinite(si) && si >= 0 && si < CHARACTER_SLOT_COUNT && characterRoster.slots[si]) {
      selectedCharacterSlotIndex = si;
      renderCharacterSelectScreen();
    }
    return;
  }
  if (e.target.closest("#characterSelectPlayBtn")) {
    if (
      selectedCharacterSlotIndex == null ||
      !Number.isFinite(selectedCharacterSlotIndex) ||
      !characterRoster.slots[selectedCharacterSlotIndex]
    ) {
      showModal("Select a character or click + to create one.");
      return;
    }
    startGameWithSelectedCharacter();
    return;
  }
  if (e.target.closest("#characterSelectLogoutBtn")) {
    logoutToLoginScreen();
  }
}

function initCharacterSelectUi() {
  initEarlyModalUi();
  if (document.documentElement.dataset.characterSelectBound === "1") return;
  document.documentElement.dataset.characterSelectBound = "1";
  document.addEventListener("click", onCharacterSelectScreenClick);
}

function logoutToLoginScreen() {
  if (typeof window !== "undefined" && window.ServerCombat?.hasSession?.() && window.ServerCombat.hasSession()) {
    showModal("Finish or leave your current fight before logging out.");
    return;
  }
  inGameSession = false;
  activeCharacterSlotIndex = null;
  selectedCharacterSlotIndex = null;
  player = null;
  combatState = null;
  characterRoster = emptyCharacterRoster();
  setGameSessionUiVisible(false);
  setCharacterSelectScreenVisible(false);
  if (typeof window !== "undefined" && window.GameStorage?.logout) {
    window.GameStorage.logout();
  }
}

async function ensureMinimalCharacterSelectUi() {
  ensureCharacterRoster();
  initCharacterSelectUi();
  setGameSessionUiVisible(false);
  setCharacterSelectScreenVisible(true);
  renderCharacterSelectScreen();
}

async function initAppAtStartup() {
  characterRoster = emptyCharacterRoster();
  player = null;
  inGameSession = false;
  activeCharacterSlotIndex = null;
  selectedCharacterSlotIndex = null;
  characterRoster = await loadCharacterRoster();
  await ensureMinimalCharacterSelectUi();
  try {
    initUi();
  } catch (err) {
    console.error("UI init failed (character select still available):", err);
  }
  hideLoadingOverlay();
}

function anyCompanionEnabled() {
  return !!(player && Array.isArray(player.companions) && player.companions.some((c) => c && c.enabled));
}

function getActorSkillLevel(actor, skillName) {
  if (!actor) return 0;
  if (skillName === "Basic Physical Attack" || skillName === "Basic Magical Attack") return 1;
  if (!isClassSkill(skillName)) return 0;
  const map = actor.classSkillLevels && typeof actor.classSkillLevels === "object" ? actor.classSkillLevels : {};
  const lv = map[skillName];
  if (typeof lv !== "number" || !Number.isFinite(lv) || lv <= 0) return 0;
  const cap = getClassSkillMaxRank(skillName);
  return Math.max(0, Math.min(cap, Math.floor(lv)));
}

function getActorSelectedProfessions(actor) {
  return Array.isArray(actor && actor.professions) ? actor.professions.slice() : [];
}

function normalizeActorProfessions(actor) {
  if (!actor || typeof actor !== "object") return [];
  const validProfIds = new Set(getProfessionDefs().map((d) => d.id));
  const maxPick = getMaxSelectedProfessions(actor);
  const next = [];
  const raw = Array.isArray(actor.professions) ? actor.professions : [];
  raw.forEach((id) => {
    const k = typeof id === "string" ? id.trim() : "";
    if (!k || !validProfIds.has(k) || next.includes(k) || next.length >= maxPick) return;
    next.push(k);
  });
  actor.professions = next;
  return next.slice();
}

function ensureActorProfessionProgress(actor) {
  if (typeof ProfessionProgression !== "undefined" && actor && typeof actor === "object") {
    ProfessionProgression.ensureProfessionProgress(actor);
  }
}

function getProfessionLabel(professionId) {
  const d = getProfessionDefById(professionId);
  return d && d.label ? d.label : String(professionId || "").replace(/_/g, " ");
}

function toggleActorProfession(actor, id) {
  const profId = String(id || "").trim();
  if (!profId || !getProfessionDefById(profId) || !actor) return false;
  const selected = normalizeActorProfessions(actor);
  const curIdx = selected.indexOf(profId);
  if (curIdx >= 0) {
    selected.splice(curIdx, 1);
    actor.professions = selected;
    return true;
  }
  if (selected.length >= getMaxSelectedProfessions(actor)) return false;
  selected.push(profId);
  actor.professions = selected;
  return true;
}

/** Total skill points spent on class skills (rank L costs L points: unlock + each upgrade). */
function totalSkillPointsSpentOnActor(actor) {
  if (!actor || !actor.classSkillLevels || typeof actor.classSkillLevels !== "object") return 0;
  let spent = 0;
  Object.entries(actor.classSkillLevels).forEach(([name, slv]) => {
    if (typeof slv === "number" && slv > 0) {
      const cap = getClassSkillMaxRank(name);
      spent += Math.max(0, Math.min(cap, Math.floor(slv)));
    }
  });
  return spent;
}

function levelUpActor(actor) {
  if (!actor) return 0;
  const maxLv = getPlayerMaxLevel();
  const startLevel = typeof actor.level === "number" && actor.level >= 1 ? Math.floor(actor.level) : 1;
  while (actor.level < maxLv) {
    const need = xpToNextLevel(actor.level);
    if (need <= 0 || actor.xp < need) break;
    actor.xp -= need;
    actor.level++;
    actor.baseAttack += 2;
    actor.maxHp = computeMaxHp(actor);
    actor.hp = actor.maxHp;
  }
  recomputeAllocPoolsFromLevel(actor);
  return Math.max(0, (typeof actor.level === "number" ? Math.floor(actor.level) : startLevel) - startLevel);
}

/** Characteristic pool = level×5 minus stat spend curve; skill pool = level minus points invested in class skills. */
function recomputeAllocPoolsFromLevel(actor) {
  if (!actor || typeof actor !== "object") return;
  const lv = typeof actor.level === "number" && actor.level >= 1 ? Math.floor(actor.level) : 1;
  const earnedChars = actor.allocPoolsCharV2 === true ? Math.max(0, (lv - 1) * 5) : lv * 5;
  actor.charPoints = Math.max(0, earnedChars - totalCharPointsAllocatedOnActor(actor));
  actor.skillPoints = Math.max(0, lv - totalSkillPointsSpentOnActor(actor));
}

/**
 * Recomputes characteristic points, skill points, and base attack after edit-mode level change.
 * Matches retrospective char-point math and per-level rewards from {@link levelUp} / {@link levelUpActor} (5 characteristic + 1 skill per level, including level 1).
 */
function syncActorProgressionForEditedLevel(actor) {
  if (!actor || typeof actor !== "object") return;
  const maxLv = getPlayerMaxLevel();
  let level = typeof actor.level === "number" && actor.level >= 1 ? Math.floor(actor.level) : 1;
  level = Math.min(maxLv, Math.max(1, level));
  actor.level = level;

  recomputeAllocPoolsFromLevel(actor);

  actor.baseAttack = 10 + Math.max(0, level - 1) * 2;
}
function getActorArmorDefense() {
  return 0;
}

function getActorCombatStaminaBaseMax() {
  return getPlayerCombatStaminaBaseMax();
}

function getActorCombatMaxStamina(actor) {
  const base = getActorCombatStaminaBaseMax();
  const fromGear = sumEquippedBonusStatsFromEquipment(actor && actor.equipment ? actor.equipment : emptyEquipment()).stamina || 0;
  return Math.max(1, base + fromGear);
}

/** Award per-member victory XP (hero + in-fight companions). */
function awardVictoryXpToParty(memberRewards) {
  if (!Array.isArray(memberRewards) || !memberRewards.length) return;
  /** @type {Array<{ name: string, newLevel: number, levelsGained: number }>} */
  const leveledUp = [];
  memberRewards.forEach((m) => {
    if (!m || !(m.xp > 0)) return;
    if (m.kind === "hero") {
      player.xp += m.xp;
      const gained = levelUp();
      if (gained > 0) {
        leveledUp.push({
          name: typeof player.name === "string" && player.name.trim() ? player.name.trim() : "Hero",
          newLevel: player.level,
          levelsGained: gained
        });
      }
      return;
    }
    if (m.kind === "companion" && typeof m.companionSlotIndex === "number") {
      const c = player.companions && player.companions[m.companionSlotIndex];
      if (!c || c === player || !c.enabled) return;
      c.xp += m.xp;
      const gained = levelUpActor(c);
      if (gained > 0) {
        leveledUp.push({
          name: typeof c.name === "string" && c.name.trim() ? c.name.trim() : `Companion ${m.companionSlotIndex + 1}`,
          newLevel: c.level,
          levelsGained: gained
        });
      }
    }
  });
  if (leveledUp.length) showLevelUpCelebrationModal(leveledUp);
}

function showLevelUpCelebrationModal(entries) {
  if (!Array.isArray(entries) || !entries.length) return;
  const rows = entries
    .map((e) => {
      const name = escapeHtml(e.name || "Fighter");
      const lv = typeof e.newLevel === "number" ? Math.floor(e.newLevel) : 1;
      const n = typeof e.levelsGained === "number" && e.levelsGained > 1 ? e.levelsGained : 1;
      const jump =
        n > 1
          ? ` gained ${n} levels and is now level ${lv}!`
          : ` reached level ${lv}!`;
      return `<p class="level-up-row"><strong>${name}</strong>${escapeHtml(jump)}</p>`;
    })
    .join("");
  showModalHtml(
    `<div class="level-up-modal">
      <h3 class="level-up-modal-title">Level up!</h3>
      <div class="level-up-modal-body">${rows}</div>
      <div class="npc-dialog-actions level-up-modal-actions">
        <button type="button" class="btn-primary" onclick="closeModal()">Close</button>
      </div>
    </div>`,
    { npcBubble: true }
  );
}

function syncCompanionHpFromCombatParty(st) {
  if (!st || !Array.isArray(st.party)) return;
  st.party.forEach((m) => {
    if (!m || m.kind !== "companion" || typeof m.companionSlotIndex !== "number") return;
    const idx = m.companionSlotIndex;
    const c = player.companions && player.companions[idx];
    if (!c || !c.enabled) return;
    c.hp = Math.max(0, Math.min(typeof m.hp === "number" ? m.hp : 0, typeof m.maxHp === "number" ? m.maxHp : c.maxHp));
  });
}

function buildStartingInventory() {
  const loadout = GAME_CONFIG && Array.isArray(GAME_CONFIG.startingLoadout) ? GAME_CONFIG.startingLoadout : [];
  const out = [];
  for (const entry of loadout) {
    if (!entry || typeof entry.name !== "string") continue;
    const name = entry.name.trim();
    if (!name || !Object.prototype.hasOwnProperty.call(GAME_CONFIG.items || {}, name)) continue;
    const rawCount = typeof entry.count === "number" ? entry.count : 1;
    const count = Math.max(1, Math.floor(rawCount));
    for (let i = 0; i < count; i++) out.push(name);
  }
  return out;
}

function getLevelingConfig() {
  return GAME_CONFIG.leveling && typeof GAME_CONFIG.leveling === "object" ? GAME_CONFIG.leveling : {};
}

function getPlayerMaxLevel() {
  const c = getLevelingConfig();
  return typeof c.maxLevel === "number" && c.maxLevel > 1 ? Math.floor(c.maxLevel) : 60;
}

/**
 * XP required to advance from `level` to `level + 1`. Returns 0 at or above max level.
 * Default curve: max(1, round(250 + 55L + 10L² + 0.35L³)).
 */
function xpToNextLevel(level) {
  const lv = Math.floor(typeof level === "number" && level > 0 ? level : 1);
  const maxLv = getPlayerMaxLevel();
  if (lv >= maxLv) return 0;
  const c = getLevelingConfig();
  const a = typeof c.xpConst === "number" && Number.isFinite(c.xpConst) ? c.xpConst : 250;
  const lin = typeof c.xpLinear === "number" && Number.isFinite(c.xpLinear) ? c.xpLinear : 55;
  const sq = typeof c.xpSquare === "number" && Number.isFinite(c.xpSquare) ? c.xpSquare : 10;
  const cub = typeof c.xpCubic === "number" && Number.isFinite(c.xpCubic) ? c.xpCubic : 0.35;
  return Math.max(1, Math.round(a + lv * lin + lv * lv * sq + lv * lv * lv * cub));
}

const DEFAULT_SKILL_RANK_STEP_BY_UNLOCK_LEVEL = [
  { maxUnlockLevel: 10, step: 5 },
  { maxUnlockLevel: 20, step: 4 },
  { maxUnlockLevel: 30, step: 3 },
  { maxUnlockLevel: 40, step: 2 },
  { maxUnlockLevel: 55, step: 1 },
  { maxUnlockLevel: 60, step: 0 }
];

function getSkillRankStepByUnlockLevelBands() {
  const c = getLevelingConfig();
  const bands = c.skillRankStepByUnlockLevel || c.skillUnlockSlotCharLevelBands;
  return Array.isArray(bands) && bands.length ? bands : DEFAULT_SKILL_RANK_STEP_BY_UNLOCK_LEVEL;
}

function getSkillCatalogUnlockLevel(skillName) {
  const cat = typeof SKILL_CATALOG !== "undefined" && SKILL_CATALOG && skillName ? SKILL_CATALOG[skillName] : null;
  return cat && typeof cat.unlock === "number" && cat.unlock > 0 ? Math.floor(cat.unlock) : 1;
}

/**
 * Rank upgrade step from catalog unlock level: unlock 1–10 → +5, 11–20 → +4, 21–30 → +3,
 * 31–40 → +2, 41–55 → +1, 56–60 → +0.
 */
function getRankStepForSkillUnlockLevel(unlockLevel) {
  const lv = Math.max(1, Math.floor(typeof unlockLevel === "number" && unlockLevel > 0 ? unlockLevel : 1));
  const bands = getSkillRankStepByUnlockLevelBands();
  for (let i = 0; i < bands.length; i++) {
    const band = bands[i];
    const maxLv =
      typeof band.maxUnlockLevel === "number" && band.maxUnlockLevel > 0
        ? Math.floor(band.maxUnlockLevel)
        : typeof band.maxSlot === "number" && band.maxSlot > 0
          ? Math.floor(band.maxSlot)
          : typeof band.maxRank === "number" && band.maxRank > 0
            ? Math.floor(band.maxRank)
            : 60;
    if (lv <= maxLv) {
      return typeof band.step === "number" && Number.isFinite(band.step) ? Math.max(0, band.step) : 5;
    }
  }
  return 0;
}

function getClassSkillMaxRank(skillName) {
  const cat = typeof SKILL_CATALOG !== "undefined" && SKILL_CATALOG && skillName ? SKILL_CATALOG[skillName] : null;
  if (cat && Array.isArray(cat.levels) && cat.levels.length > 0) return cat.levels.length;
  return 5;
}

/** First unlock level from `SKILL_CATALOG` (`unlock` field). */
function getMinCharacterLevelToUnlockSkill(skillName) {
  return getSkillCatalogUnlockLevel(skillName);
}

function getRankStepForSkill(skillName) {
  return getRankStepForSkillUnlockLevel(getSkillCatalogUnlockLevel(skillName));
}

/**
 * Character level to train `skillName` to `targetRank`.
 * Rank 1 = unlock level; each further rank adds this skill's band step (e.g. unlock 5 → ranks at 5, 10, 15…).
 */
function getMinCharacterLevelForSkillAtRank(skillName, targetRank) {
  const r = Math.max(1, Math.floor(typeof targetRank === "number" && targetRank > 0 ? targetRank : 1));
  const unlockLv = getMinCharacterLevelToUnlockSkill(skillName);
  const step = getRankStepForSkill(skillName);
  if (r <= 1) return unlockLv;
  return unlockLv + (r - 1) * step;
}
function actorMeetsSkillRankLevel(actor, skillName, targetRank) {
  if (!actor) return false;
  const actorLv = typeof actor.level === "number" && actor.level > 0 ? Math.floor(actor.level) : 1;
  const r = Math.max(1, Math.floor(typeof targetRank === "number" && targetRank > 0 ? targetRank : 1));
  return actorLv >= getMinCharacterLevelForSkillAtRank(skillName, r);
}

const DEFAULT_CLASS_ID = "adventurer";

const ADVENTURER_UI_CLASS = {
  id: "adventurer",
  label: "Hero",
  role: "",
  passive: "",
  primaryStats: ["STR", "DEX", "VIT", "INT"],
  starterSkills: [],
  skills: []
};

let CLASS_SKILL_MAP = {};

/** PNG in `Assets/Skills/` named from skill title (snake_case), matching shipped art files. */
function skillCatalogAssetPngPath(skillName) {
  if (!skillName || typeof skillName !== "string") return "";
  if (skillName === "Basic Physical Attack") return "Assets/Skills/basic_physical_attack.png";
  if (skillName === "Basic Magical Attack") return "Assets/Skills/basic_magic_attack.png";
  const slug = skillName
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");
  return slug ? `Assets/Skills/${slug}.png` : "";
}

function rebuildClassSkillMapFromCatalog() {
  const m = {};
  if (typeof SKILL_CATALOG === "object" && SKILL_CATALOG) {
    Object.keys(SKILL_CATALOG).forEach((name) => {
      const c = SKILL_CATALOG[name];
      const stam = typeof c.stamina === "number" ? c.stamina : 2;
      const passiveOnly = !!c.passiveOnly;
      const lastLv = c.levels && c.levels[4] ? c.levels[4] : null;
      const aoeAll = c.pattern === "event_horizon" || (c.pattern === "arcane_collapse" && lastLv && lastLv.aoeAdj >= 99);
      const dk = passiveOnly ? undefined : c.damageKind === "magic" ? "magic" : "physical";
      m[name] = {
        name,
        classId: "adventurer",
        tier: "early",
        staminaCost: stam,
        combatMultiplier: passiveOnly ? undefined : 1,
        damageKind: dk,
        combatAoe: aoeAll ? "all_enemies" : undefined,
        combatTags: [],
        passiveOnly,
        description: ""
      };
    });
  }
  CLASS_SKILL_MAP = m;
}

function injectClassSkillsIntoConfig() {
  rebuildClassSkillMapFromCatalog();
  const skillArr = Array.isArray(GAME_CONFIG.skills) ? GAME_CONFIG.skills : [];
  const existingByName = new Map();
  skillArr.forEach((srow, i) => {
    const n = srow && typeof srow.name === "string" ? srow.name : "";
    if (n) existingByName.set(n, i);
  });
  Object.values(CLASS_SKILL_MAP).forEach((sk) => {
    const next = {
      name: sk.name,
      bonus: 0,
      combatMultiplier: typeof sk.combatMultiplier === "number" ? sk.combatMultiplier : undefined,
      staminaCost: sk.staminaCost,
      damageKind: sk.damageKind || "physical",
      combatAoe: sk.combatAoe,
      combatTags: Array.isArray(sk.combatTags) ? sk.combatTags : [],
      image: skillCatalogAssetPngPath(sk.name),
      description: sk.description
    };
    if (existingByName.has(sk.name)) {
      const idx = existingByName.get(sk.name);
      const prev = skillArr[idx] && typeof skillArr[idx] === "object" ? skillArr[idx] : {};
      skillArr[idx] = { ...prev, ...next };
      return;
    }
    skillArr.push(next);
  });
  GAME_CONFIG.skills = skillArr;
}

injectClassSkillsIntoConfig();

function getClassDef(classId) {
  return ADVENTURER_UI_CLASS;
}

function getClassSkillDefByName(skillName) {
  return CLASS_SKILL_MAP[skillName] || null;
}

function getSkillDef(skillName) {
  if (!skillName) return null;
  return GAME_CONFIG.skills.find((s) => s.name === skillName) || null;
}

function isClassSkill(skillName) {
  return !!getClassSkillDefByName(skillName);
}
function getPlayerSkillLevel(skillName) {
  if (skillName === "Basic Physical Attack" || skillName === "Basic Magical Attack") return 1;
  if (!isClassSkill(skillName)) return 0;
  const map = player && player.classSkillLevels && typeof player.classSkillLevels === "object" ? player.classSkillLevels : {};
  const lv = map[skillName];
  if (typeof lv !== "number" || !Number.isFinite(lv) || lv <= 0) return 0;
  const cap = getClassSkillMaxRank(skillName);
  return Math.max(0, Math.min(cap, Math.floor(lv)));
}

function getClassSkillPowerMultiplier(skillName) {
  return getClassSkillPowerMultiplierForActor(player, skillName);
}

function getClassSkillPowerMultiplierForActor(actor, skillName) {
  const lv = getActorSkillLevel(actor, skillName);
  if (!lv) return 1;
  return 1 + 0.2 * (lv - 1);
}

function syncPlayerClassSkillList(p) {
  if (!p.classSkillLevels || typeof p.classSkillLevels !== "object") p.classSkillLevels = {};
  const basics = ["Basic Physical Attack", "Basic Magical Attack"];
  const out = basics.slice();
  if (typeof UNIFIED_SKILL_ORDER !== "undefined" && UNIFIED_SKILL_ORDER) {
    UNIFIED_SKILL_ORDER.forEach((name) => {
      if (basics.includes(name)) return;
      const lv = p.classSkillLevels[name];
      if (typeof lv === "number" && lv > 0) out.push(name);
    });
  }
  p.skills = out;
}

const SKILL_BAR_SLOT_COUNT = 12;

function isCombatCatalogSkillName(skillName) {
  if (!skillName || typeof skillName !== "string") return false;
  const cat = typeof SKILL_CATALOG !== "undefined" && SKILL_CATALOG && SKILL_CATALOG[skillName];
  if (cat && cat.passiveOnly) return false;
  const cfg = getSkillDef(skillName);
  return !!(cfg && typeof cfg.combatMultiplier === "number");
}

function actorOwnsSkillForBar(actor, skillName) {
  if (!actor || !skillName) return false;
  if (skillName === "Basic Physical Attack" || skillName === "Basic Magical Attack") return true;
  return getActorSkillLevel(actor, skillName) > 0;
}

function defaultSkillBarSlotsFromSyncedSkills(actor) {
  const out = Array(SKILL_BAR_SLOT_COUNT).fill(null);
  const names = Array.isArray(actor.skills) ? actor.skills : [];
  let i = 0;
  for (let k = 0; k < names.length && i < SKILL_BAR_SLOT_COUNT; k++) {
    const name = names[k];
    if (!name || typeof name !== "string") continue;
    if (!isCombatCatalogSkillName(name)) continue;
    out[i++] = name;
  }
  return out;
}

function ensureActorSkillBar(actor) {
  if (!actor || typeof actor !== "object") return;
  if (!Array.isArray(actor.skillBarSlots) || actor.skillBarSlots.length !== SKILL_BAR_SLOT_COUNT) {
    syncPlayerClassSkillList(actor);
    actor.skillBarSlots = defaultSkillBarSlotsFromSyncedSkills(actor);
    return;
  }
  for (let i = 0; i < SKILL_BAR_SLOT_COUNT; i++) {
    const v = actor.skillBarSlots[i];
    if (v == null || v === "") {
      actor.skillBarSlots[i] = null;
      continue;
    }
    const s = String(v).trim();
    if (!s || !isClassSkill(s) || !isCombatCatalogSkillName(s) || !actorOwnsSkillForBar(actor, s)) {
      actor.skillBarSlots[i] = null;
    } else {
      actor.skillBarSlots[i] = s;
    }
  }
}

function isSkillSlottedForActor(actor, skillName) {
  if (!actor || !skillName) return false;
  ensureActorSkillBar(actor);
  return actor.skillBarSlots.some((s) => s === skillName);
}

function resolveSkillBarTargetActorFromEl(el) {
  const page = el && el.closest && el.closest("[data-overview-roster-tab]");
  const tab =
    page && page.dataset && page.dataset.overviewRosterTab != null && page.dataset.overviewRosterTab !== ""
      ? page.dataset.overviewRosterTab
      : getCharacterRosterTab();
  return getRosterActorFromTab(tab);
}

function applySkillBarDropFromCatalog(actor, skillName, targetIdx) {
  if (!actor || !skillName) return false;
  const name = String(skillName).trim();
  if (!name || !isClassSkill(name) || !isCombatCatalogSkillName(name)) return false;
  if (!actorOwnsSkillForBar(actor, name)) return false;
  const ti = Math.max(0, Math.min(SKILL_BAR_SLOT_COUNT - 1, Math.floor(targetIdx)));
  ensureActorSkillBar(actor);
  for (let j = 0; j < SKILL_BAR_SLOT_COUNT; j++) {
    if (actor.skillBarSlots[j] === name) actor.skillBarSlots[j] = null;
  }
  actor.skillBarSlots[ti] = name;
  return true;
}

function applySkillBarSlotSwap(actor, fromIdx, toIdx) {
  ensureActorSkillBar(actor);
  const a = Math.max(0, Math.min(SKILL_BAR_SLOT_COUNT - 1, Math.floor(fromIdx)));
  const b = Math.max(0, Math.min(SKILL_BAR_SLOT_COUNT - 1, Math.floor(toIdx)));
  const tmp = actor.skillBarSlots[a];
  actor.skillBarSlots[a] = actor.skillBarSlots[b];
  actor.skillBarSlots[b] = tmp;
  return true;
}

/** Move a slotted skill to another bar index; clears the source slot (swap if target is occupied). */
function applySkillBarMoveFromSlot(actor, fromIdx, toIdx) {
  ensureActorSkillBar(actor);
  const a = Math.max(0, Math.min(SKILL_BAR_SLOT_COUNT - 1, Math.floor(fromIdx)));
  const b = Math.max(0, Math.min(SKILL_BAR_SLOT_COUNT - 1, Math.floor(toIdx)));
  if (a === b) return false;
  const name = actor.skillBarSlots[a];
  if (!name) return false;
  if (!actor.skillBarSlots[b]) {
    actor.skillBarSlots[b] = name;
    actor.skillBarSlots[a] = null;
    return true;
  }
  return applySkillBarSlotSwap(actor, a, b);
}

function getSkillBarRemoveDropZone(el) {
  if (!el || !el.closest) return null;
  return el.closest(
    ".skills-pool-scroll, .skills-tab-inner, .class-skills-list, .class-skill-row, .skills-bar-host"
  );
}

function getCombatSkillNameForBarSlot(actor, slotIndex) {
  if (!actor) return null;
  ensureActorSkillBar(actor);
  const i = Math.max(0, Math.min(SKILL_BAR_SLOT_COUNT - 1, Math.floor(slotIndex)));
  const name = actor.skillBarSlots[i];
  if (!name || typeof name !== "string") return null;
  if (!actorOwnsSkillForBar(actor, name) || !isCombatCatalogSkillName(name)) return null;
  return name;
}

function getFightSkillBarHotkeySlotIndex(key) {
  if (key >= "1" && key <= "9") return key.charCodeAt(0) - "1".charCodeAt(0);
  if (key === "0") return 9;
  return -1;
}

function getFightActiveSkillBarActor() {
  const st = combatState;
  if (!st || st.phase !== "player") return null;
  const active = getActivePartyMember(st);
  if (!active) return null;
  if (active.kind === "hero") return player;
  if (typeof active.companionSlotIndex === "number") {
    return player.companions && player.companions[active.companionSlotIndex];
  }
  return null;
}

function tryFightSkillBarHotkey(e) {
  if (!isFightOverlayOpen()) return false;
  const st = combatState;
  if (!st || st.phase !== "player") return false;
  if (e.ctrlKey || e.metaKey || e.altKey) return false;
  const slotIdx = getFightSkillBarHotkeySlotIndex(e.key);
  if (slotIdx < 0) return false;
  const actor = getFightActiveSkillBarActor();
  const skillName = getCombatSkillNameForBarSlot(actor, slotIdx);
  if (!skillName) return false;
  e.preventDefault();
  activeActorAction("skill", skillName);
  return true;
}

function tryFightEndTurnHotkey(e) {
  if (!isFightOverlayOpen()) return false;
  const st = combatState;
  if (!st) return false;
  if (st.phase === "prep") {
    if (e.ctrlKey || e.metaKey || e.altKey) return false;
    const key = e.key;
    if (key !== " " && key !== "F1") return false;
    if (
      st.serverAuthoritative &&
      window.ServerCombat?.isFightHost?.() &&
      window.ServerCombat?.submitAction
    ) {
      e.preventDefault();
      void window.ServerCombat.submitAction({ type: "ready" });
      return true;
    }
    return false;
  }
  if (st.phase !== "player") return false;
  if (!getActivePartyMember(st)) return false;
  if (e.ctrlKey || e.metaKey || e.altKey) return false;
  const key = e.key;
  if (key !== " " && key !== "F1") return false;
  e.preventDefault();
  endActiveActorTurn(false);
  return true;
}

function refreshSkillBarUiAfterChange() {
  save();
  if (isSkillsPanelOpen()) refreshSkillsPanelSubpanelInPlace();
  else render();
}

function applySkillBarClearSlot(actor, idx) {
  ensureActorSkillBar(actor);
  const i = Math.max(0, Math.min(SKILL_BAR_SLOT_COUNT - 1, Math.floor(idx)));
  actor.skillBarSlots[i] = null;
  return true;
}

const PORTRAIT_GENDER_IDS = ["male", "female"];

const COMPANION_PORTRAIT_BASE_BY_GENDER = {
  male: "Assets/Character/male_template.png",
  female: "Assets/Character/female_character.png"
};

function normalizePortraitGender(raw) {
  const g = String(raw || "")
    .trim()
    .toLowerCase();
  return g === "female" ? "female" : "male";
}

function getPortraitCharacterPresets() {
  return GAME_CONFIG.portraitCharacterPresets && typeof GAME_CONFIG.portraitCharacterPresets === "object"
    ? GAME_CONFIG.portraitCharacterPresets
    : {};
}

function getPortraitPresetPack(gender) {
  const g = normalizePortraitGender(gender);
  const presets = getPortraitCharacterPresets();
  const pack = presets[g] && typeof presets[g] === "object" ? presets[g] : null;
  if (pack) return pack;
  const fallback = presets.male && typeof presets.male === "object" ? presets.male : null;
  return fallback;
}

function getDefaultPortraitBaseLayout(gender) {
  const pack = getPortraitPresetPack(gender);
  const raw = pack && pack.baseLayout && typeof pack.baseLayout === "object" ? pack.baseLayout : null;
  if (!raw) return { offsetXPct: 0, offsetYPct: 0, rotDeg: 0, scalePct: 100 };
  return {
    offsetXPct: clampPortraitLayoutPct(raw.offsetXPct),
    offsetYPct: clampPortraitLayoutPct(raw.offsetYPct),
    rotDeg: clampPortraitLayoutRotDeg(raw.rotDeg),
    scalePct: clampPortraitLayoutScalePct(raw.scalePct)
  };
}

function getDefaultBottomHudPortraitLayout(gender) {
  const pack = getPortraitPresetPack(gender);
  const raw = pack && pack.bottomHudLayout && typeof pack.bottomHudLayout === "object" ? pack.bottomHudLayout : null;
  if (!raw) return { offsetXPct: 0, offsetYPct: 0, rotDeg: 0, scalePct: 100 };
  return {
    offsetXPct: clampPortraitLayoutPct(raw.offsetXPct),
    offsetYPct: clampPortraitLayoutPct(raw.offsetYPct),
    rotDeg: clampPortraitLayoutRotDeg(raw.rotDeg),
    scalePct: clampPortraitLayoutScalePct(raw.scalePct)
  };
}

function findNearestScrollableContainer(el) {
  let cur = el;
  while (cur && cur !== document.body) {
    if (cur instanceof HTMLElement && cur.scrollHeight > cur.clientHeight + 1) return cur;
    cur = cur.parentElement;
  }
  return null;
}

function unlockOrUpgradeClassSkill(skillName, sourceEl, actor) {
  const target = actor || player;
  const sk = getClassSkillDefByName(skillName);
  if (!sk) return false;
  if (isSkillsPanelOpen()) {
    const near = sourceEl ? findNearestScrollableContainer(sourceEl) : null;
    if (near) {
      overviewSkillsScrollTop = Math.max(0, Math.floor(near.scrollTop || 0));
      const row = sourceEl ? sourceEl.closest("[data-class-skill-row]") : null;
      if (row) {
        const hostRect = near.getBoundingClientRect();
        const rowRect = row.getBoundingClientRect();
        overviewSkillsScrollAnchor = {
          skillName,
          offsetY: Math.max(0, Math.floor(rowRect.top - hostRect.top))
        };
      } else {
        overviewSkillsScrollAnchor = null;
      }
    } else {
      captureOverviewSkillsScroll();
    }
  }
  if (!target.classSkillLevels || typeof target.classSkillLevels !== "object") target.classSkillLevels = {};
  if (skillName === "Basic Physical Attack" || skillName === "Basic Magical Attack") return false;
  const cur = getActorSkillLevel(target, skillName);
  const maxRank = getClassSkillMaxRank(skillName);
  const nextRank = cur + 1;
  if (nextRank > maxRank) return false;
  const actorLv = typeof target.level === "number" && target.level > 0 ? Math.floor(target.level) : 1;
  const rankReq = getMinCharacterLevelForSkillAtRank(skillName, nextRank);
  if (actorLv < rankReq) {
    const msg =
      cur <= 0
        ? `Requires character level ${rankReq} to unlock this skill.`
        : `Requires character level ${rankReq} for skill rank ${nextRank}.`;
    showModal(msg);
    return false;
  }
  if (typeof target.skillPoints !== "number" || target.skillPoints < 1) {
    showModal("Not enough skill points.");
    return false;
  }
  if (isOnlineGameplayMode() && activeCharacterSlotIndex != null && window.GameStorage?.playerUpgradeSkill) {
    void (async () => {
      try {
        const body = await window.GameStorage.playerUpgradeSkill({
          slotIndex: activeCharacterSlotIndex,
          skillName,
          ...resolveOnlineTargetFromActor(target)
        });
        await applyOnlineActionResponse(body);
        const inPlace = isSkillsPanelOpen() ? refreshSkillsPanelSubpanelInPlace() : false;
        if (!inPlace) render();
        restoreOverviewSkillsScroll();
      } catch (err) {
        showModal(err && err.message ? err.message : "Could not upgrade skill.");
      }
    })();
    return true;
  }
  showServerActionRequired();
  return false;
}

const defaultPlayer = () => {
  const st = GAME_CONFIG.worldMap.defaultStart;
  const classSkillLevels = {};
  const p = {
    name: "Hero",
    level: 1,
    xp: 0,
    hp: 100,
    maxHp: 100,
    str: 5,
    dex: 5,
    vit: 5,
    int: 5,
    baseAttack: 10,
    charPoints: 0,
    gold: 0,
    classId: DEFAULT_CLASS_ID,
    skillPoints: 1,
    classSkillLevels,
    skills: [],
    professions: [],
    professionProgress: {},
    inventory: buildStartingInventory(),
    equipment: getStarterEquipment(),
    portraitGender: "male",
    portraitLayouts: {},
    portraitLayoutLastExport: "",
    theme: "medieval",
    charPointsRetroDone: true,
    allocPoolsBindToLevelV2: true,
    allocPoolsCharV2: true,
    worldMap: {
      x: st.x,
      y: st.y,
      cells: {},
      scenePickups: {},
      sceneLayout: {},
      sceneEdits: {},
      portalWorldById: {},
      spawnPressure: { monsters: {} }
    },
    editMode: false
  };
  p.maxHp = computeMaxHp(p);
  p.hp = p.maxHp;
  syncPlayerClassSkillList(p);
  ensureActorSkillBar(p);
  recomputeAllocPoolsFromLevel(p);
  return p;
};

let player = null;

/** Merge {@link GAME_CONFIG.worldMap.cityPortals} into coordinateCells (one waygate per entry, only on the anchor tile x,y). */
function applyCityPortalsFromConfig() {
  const wm = GAME_CONFIG.worldMap;
  if (!wm || !Array.isArray(wm.cityPortals)) return;
  wm.coordinateBackgrounds = wm.coordinateBackgrounds && typeof wm.coordinateBackgrounds === "object" ? wm.coordinateBackgrounds : {};
  wm.coordinateCells = wm.coordinateCells && typeof wm.coordinateCells === "object" ? wm.coordinateCells : {};
  for (const p of wm.cityPortals) {
    if (typeof p.x !== "number" || typeof p.y !== "number" || typeof p.name !== "string" || !p.name.trim()) continue;
    const nameTrim = p.name.trim();
    const anchorKey = worldMapKey(p.x, p.y);
    const theme = typeof p.theme === "string" && /^[a-zA-Z0-9_-]+$/.test(p.theme) ? p.theme : "portal-theme-default";
    const label = typeof p.label === "string" && p.label.trim() ? p.label.trim() : "Waygate";
    const portalId = `portal_${anchorKey}`;
    const portalEl = { type: "portal", id: portalId, label, city: nameTrim, theme, editable: true };
    if (typeof p.leftPct === "number" && Number.isFinite(p.leftPct)) portalEl.leftPct = clampScenePct(p.leftPct);
    if (typeof p.topPct === "number" && Number.isFinite(p.topPct)) portalEl.topPct = clampScenePct(p.topPct);
    if (typeof p.scalePct === "number" && Number.isFinite(p.scalePct)) portalEl.scalePct = clampSceneScalePct(p.scalePct);
    const prev = wm.coordinateCells[anchorKey];
    if (prev && prev.kind === "scene") {
      const raw = Array.isArray(prev.elements) ? prev.elements : [];
      const elements = raw.map((e) => (e && typeof e === "object" ? { ...e } : e));
      const idx = elements.findIndex((e) => e && e.type === "portal" && e.id === portalId);
      if (idx >= 0) elements[idx] = { ...elements[idx], ...portalEl };
      else elements.push(portalEl);
      wm.coordinateCells[anchorKey] = {
        kind: "scene",
        title: typeof prev.title === "string" ? prev.title : "",
        description: typeof prev.description === "string" ? prev.description : "",
        elements
      };
    } else {
      wm.coordinateCells[anchorKey] = {
        kind: "scene",
        title: "",
        description: "",
        elements: [portalEl]
      };
    }
  }
}

/**
 * Removes the config city portal waygate from other tiles in the same city when saved in {@link player.worldMap.sceneEdits}
 * (e.g. after older builds replicated the portal to every city cell).
 */
function pruneDuplicateCityPortalsFromSceneEdits() {
  const wm = GAME_CONFIG.worldMap;
  if (!wm || !Array.isArray(wm.cityPortals)) return;
  const edits = player.worldMap.sceneEdits;
  if (!edits || typeof edits !== "object") return;
  let changed = false;
  for (const p of wm.cityPortals) {
    if (typeof p.x !== "number" || typeof p.y !== "number" || typeof p.name !== "string" || !p.name.trim()) continue;
    const anchorKey = worldMapKey(p.x, p.y);
    const portalId = `portal_${anchorKey}`;
    const nameTrim = p.name.trim();
    for (const k of Object.keys(edits)) {
      if (k === anchorKey) continue;
      const { x, y } = parseWorldMapKey(k);
      if (getWorldMapCityName(x, y) !== nameTrim) continue;
      const edit = edits[k];
      if (!edit || edit.kind !== "scene" || !Array.isArray(edit.elements)) continue;
      const next = edit.elements.filter((el) => !(el && el.type === "portal" && el.id === portalId));
      if (next.length === edit.elements.length) continue;
      changed = true;
      const titleEmpty = !edit.title || !String(edit.title).trim();
      const descEmpty = !edit.description || !String(edit.description).trim();
      if (next.length === 0 && titleEmpty && descEmpty) {
        delete edits[k];
      } else {
        edit.elements = next;
      }
    }
  }
  if (changed) save();
}

const PLAYER_SAVE_KEY = "player";
const PLAYER_SAVE_BACKUP_KEY = "player_backup";
const CHARACTER_ROSTER_KEY = "character_roster_v1";

function parseSavedPlayerJson(raw) {
  if (typeof raw !== "string" || !raw.trim()) return null;
  try {
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

function salvagePlayerFromRaw(rawObj) {
  const base = defaultPlayer();
  const src = rawObj && typeof rawObj === "object" ? rawObj : {};
  const worldMapSrc = src.worldMap && typeof src.worldMap === "object" ? src.worldMap : {};
  const eqSrc = src.equipment && typeof src.equipment === "object" ? src.equipment : {};
  return {
    ...base,
    ...src,
    inventory: Array.isArray(src.inventory) ? src.inventory.filter((n) => typeof n === "string" && !!n) : base.inventory,
    professions: Array.isArray(src.professions) ? src.professions.filter((id) => typeof id === "string" && !!id) : [],
    classSkillLevels:
      src.classSkillLevels && typeof src.classSkillLevels === "object" ? src.classSkillLevels : base.classSkillLevels,
    equipment: { ...emptyEquipment(), ...eqSrc },
    worldMap: { ...base.worldMap, ...worldMapSrc }
  };
}

function loadPlayer() {
  const tryUse = (obj) => {
    if (!obj || typeof obj !== "object") return null;
    try {
      migratePlayer(obj);
      return obj;
    } catch {
      // Keep progress if migration fails on old/partial save shapes.
      const salvage = salvagePlayerFromRaw(obj);
      try {
        migratePlayer(salvage);
      } catch {
        /* Keep salvaged raw state as a last resort. */
      }
      return salvage;
    }
  };
  const fromPrimary = tryUse(parseSavedPlayerJson(localStorage.getItem(PLAYER_SAVE_KEY)));
  if (fromPrimary) return fromPrimary;
  const fromBackup = tryUse(parseSavedPlayerJson(localStorage.getItem(PLAYER_SAVE_BACKUP_KEY)));
  if (fromBackup) return fromBackup;
  return defaultPlayer();
}

/** Prepare active hero after character select (world portals, companions). */
function initPlayerSession() {
  if (!player) return;
  ensurePlayerCompanions(player);
  applyCityPortalsFromConfig();
  pruneDuplicateCityPortalsFromSceneEdits();
}

function migratePlayer(p) {
  if (typeof p.name !== "string" || !p.name.trim()) p.name = "Hero";
  const maxLv = getPlayerMaxLevel();
  if (typeof p.level !== "number" || p.level < 1) p.level = 1;
  else if (p.level > maxLv) p.level = maxLv;
  if (typeof p.allocPoolsCharV2 !== "boolean") p.allocPoolsCharV2 = false;
  if (typeof p.str !== "number") p.str = STAT_CHAR_ALLOC_FLOOR;
  if (typeof p.dex !== "number") {
    p.dex = typeof p.agi === "number" && Number.isFinite(p.agi) ? p.agi : STAT_CHAR_ALLOC_FLOOR;
  }
  if (Object.prototype.hasOwnProperty.call(p, "agi")) delete p.agi;
  if (typeof p.vit !== "number") p.vit = STAT_CHAR_ALLOC_FLOOR;
  if (typeof p.int !== "number") p.int = STAT_CHAR_ALLOC_FLOOR;
  if (!p.theme || !GAME_CONFIG.themes[p.theme]) p.theme = "medieval";
  if (!Array.isArray(p.inventory)) p.inventory = [];
  ensurePlayerPetState(p);
  reconcilePetInventoryInstances(p);
  if (!p.classSkillLevels || typeof p.classSkillLevels !== "object") p.classSkillLevels = {};
  if (typeof SKILL_CATALOG === "object" && SKILL_CATALOG) {
    const next = {};
    Object.keys(p.classSkillLevels).forEach((k) => {
      if (k === "Basic Physical Attack" || k === "Basic Magical Attack") return;
      if (!SKILL_CATALOG[k]) return;
      const lv = p.classSkillLevels[k];
      if (typeof lv === "number" && lv > 0) next[k] = Math.min(getClassSkillMaxRank(k), Math.floor(lv));
    });
    p.classSkillLevels = next;
  }
  p.classId = DEFAULT_CLASS_ID;
  if (typeof p.skillPoints !== "number" || p.skillPoints < 0) {
    p.skillPoints = Math.max(0, typeof p.level === "number" ? p.level : 1);
  }
  syncPlayerClassSkillList(p);
  ensureActorSkillBar(p);
  normalizeActorProfessions(p);
  const eq = p.equipment || {};
  const base = emptyEquipment();
  EQUIP_SLOTS.forEach((s) => {
    if (Object.prototype.hasOwnProperty.call(eq, s.id)) base[s.id] = eq[s.id];
  });
  if (Object.prototype.hasOwnProperty.call(eq, "gloves") && base.bracelet == null) base.bracelet = eq.gloves;
  if (Object.prototype.hasOwnProperty.call(eq, "armor") && base.chest == null) base.chest = eq.armor;
  p.equipment = base;
  enforceOffhandRuleForEquipment(p.equipment, p.inventory);
  /** Legacy names → Primate Bracelet (bracelet slot); head-worn circlet moves off head. */
  (function migrateToJungleBracelet() {
    const target = "Primate Bracelet";
    const legacyBases = new Set(["Vine Gloves", "Jungle Circlet", "Jungle Bracelet"]);
    const remap = (s) => {
      if (typeof s !== "string" || !s) return s;
      const { baseName, rarityId } = splitItemInstanceName(s);
      if (!legacyBases.has(baseName)) return s;
      return rarityId ? makeRarityItemInstanceName(target, rarityId) : target;
    };
    const placeBraceletOrInv = (next) => {
      if (!p.equipment.bracelet) p.equipment.bracelet = next;
      else if (Array.isArray(p.inventory)) p.inventory.push(next);
    };
    const hd = p.equipment && p.equipment.head;
    if (typeof hd === "string" && hd && legacyBases.has(getItemBaseName(hd))) {
      const next = remap(hd);
      p.equipment.head = null;
      placeBraceletOrInv(next);
    }
    const br = p.equipment && p.equipment.bracelet;
    if (typeof br === "string" && br && legacyBases.has(getItemBaseName(br))) {
      p.equipment.bracelet = remap(br);
    }
    EQUIP_SLOTS.forEach((slot) => {
      if (slot.id === "head" || slot.id === "bracelet") return;
      const n = p.equipment[slot.id];
      if (typeof n !== "string" || !n || !legacyBases.has(getItemBaseName(n))) return;
      const next = remap(n);
      p.equipment[slot.id] = null;
      placeBraceletOrInv(next);
    });
    if (Array.isArray(p.inventory)) {
      p.inventory = p.inventory.map((entry) => (typeof entry === "string" ? remap(entry) : entry));
    }
  })();
  (function migrateJungleBootsToPrimateBoots() {
    const oldBase = "Jungle Boots";
    const newBase = "Primate Boots";
    const remap = (s) => {
      if (typeof s !== "string" || !s) return s;
      const { baseName, rarityId } = splitItemInstanceName(s);
      if (baseName !== oldBase) return s;
      return rarityId ? makeRarityItemInstanceName(newBase, rarityId) : newBase;
    };
    const ft = p.equipment && p.equipment.feet;
    if (typeof ft === "string" && ft && getItemBaseName(ft) === oldBase) {
      p.equipment.feet = remap(ft);
    }
    if (Array.isArray(p.inventory)) {
      p.inventory = p.inventory.map((entry) => (typeof entry === "string" ? remap(entry) : entry));
    }
  })();
  (function migrateSpiritAmuletToHeartOfTheJungle() {
    const oldBase = "Spirit Amulet";
    const newBase = "Heart of the Jungle";
    const remap = (s) => {
      if (typeof s !== "string" || !s) return s;
      const { baseName, rarityId } = splitItemInstanceName(s);
      if (baseName !== oldBase) return s;
      return rarityId ? makeRarityItemInstanceName(newBase, rarityId) : newBase;
    };
    const am = p.equipment && p.equipment.amulet;
    if (typeof am === "string" && am && getItemBaseName(am) === oldBase) {
      p.equipment.amulet = remap(am);
    }
    if (Array.isArray(p.inventory)) {
      p.inventory = p.inventory.map((entry) => (typeof entry === "string" ? remap(entry) : entry));
    }
  })();
  const removedLegacyItemBases = new Set([
    "Energy Cell",
    "Wolf Pelt",
    "Frozen Core",
    "Skitter Ring",
    "Gorilla Hide Armor",
    "Echo Band",
    "Soul Loop"
  ]);
  EQUIP_SLOTS.forEach((s) => {
    const n = p.equipment[s.id];
    if (typeof n !== "string" || !n) return;
    if (removedLegacyItemBases.has(splitItemInstanceName(n).baseName)) p.equipment[s.id] = null;
  });
  if (Array.isArray(p.inventory)) {
    p.inventory = p.inventory.filter((entry) => {
      if (typeof entry !== "string" || !entry) return true;
      return !removedLegacyItemBases.has(splitItemInstanceName(entry).baseName);
    });
  }
  enforceOffhandRuleForEquipment(p.equipment, p.inventory);
  if (typeof p.charPoints !== "number" || p.charPoints < 0) p.charPoints = 0;
  if (!p.portraitGender) p.portraitGender = "male";
  ensurePortraitLayoutsStoreForOwner(p);
  if (p.portraitLayout && typeof p.portraitLayout === "object" && Object.keys(p.portraitLayout).length) {
    Object.assign(p.portraitLayouts.male.equipment, p.portraitLayout);
  }
  if (p.portraitBaseLayout && typeof p.portraitBaseLayout === "object") {
    p.portraitLayouts.male.base = p.portraitBaseLayout;
  }
  if (p.bottomHudPortraitLayout && typeof p.bottomHudPortraitLayout === "object") {
    p.portraitLayouts.male.bottomHud = p.bottomHudPortraitLayout;
  }
  if (typeof p.portraitLayoutLastExport !== "string") p.portraitLayoutLastExport = "";
  /** One-time retrospective: earned characteristic points = level×5; stats above 10 cost by the same curve as live spending. */
  if (!p.charPointsRetroDone) {
    recomputeAllocPoolsFromLevel(p);
    p.charPointsRetroDone = true;
  }
  if (!p.allocPoolsBindToLevelV2) {
    p.allocPoolsBindToLevelV2 = true;
  }
  recomputeAllocPoolsFromLevel(p);
  p.maxHp = computeMaxHp(p);
  if (typeof p.hp !== "number" || p.hp <= 0) p.hp = p.maxHp;
  p.hp = Math.min(p.hp, p.maxHp);
  if (!p.worldMap || typeof p.worldMap.x !== "number" || typeof p.worldMap.y !== "number") {
    const st = GAME_CONFIG.worldMap.defaultStart;
    const prevCells = p.worldMap && typeof p.worldMap.cells === "object" ? p.worldMap.cells : {};
    const prevPickups = p.worldMap && typeof p.worldMap.scenePickups === "object" ? p.worldMap.scenePickups : {};
    const prevLayout = p.worldMap && typeof p.worldMap.sceneLayout === "object" ? p.worldMap.sceneLayout : {};
    const prevEdits = p.worldMap && typeof p.worldMap.sceneEdits === "object" ? p.worldMap.sceneEdits : {};
    const prevPortalWorld =
      p.worldMap && typeof p.worldMap.portalWorldById === "object" ? p.worldMap.portalWorldById : {};
    const prevSpawnPressure =
      p.worldMap && p.worldMap.spawnPressure && typeof p.worldMap.spawnPressure === "object"
        ? p.worldMap.spawnPressure
        : { monsters: {} };
    p.worldMap = {
      x: st.x,
      y: st.y,
      cells: prevCells,
      scenePickups: prevPickups,
      sceneLayout: prevLayout,
      sceneEdits: prevEdits,
      portalWorldById: prevPortalWorld,
      spawnPressure: prevSpawnPressure
    };
  } else if (!p.worldMap.cells || typeof p.worldMap.cells !== "object") {
    p.worldMap.cells = {};
  }
  if (!p.worldMap.scenePickups || typeof p.worldMap.scenePickups !== "object") p.worldMap.scenePickups = {};
  if (!p.worldMap.sceneLayout || typeof p.worldMap.sceneLayout !== "object") p.worldMap.sceneLayout = {};
  if (!p.worldMap.sceneEdits || typeof p.worldMap.sceneEdits !== "object") p.worldMap.sceneEdits = {};
  if (!p.worldMap.portalWorldById || typeof p.worldMap.portalWorldById !== "object") p.worldMap.portalWorldById = {};
  if (!p.worldMap.spawnPressure || typeof p.worldMap.spawnPressure !== "object") p.worldMap.spawnPressure = { monsters: {} };
  if (!p.worldMap.spawnPressure.monsters || typeof p.worldMap.spawnPressure.monsters !== "object") {
    p.worldMap.spawnPressure.monsters = {};
  }
  if (p.worldMap.cityPortalCoords && typeof p.worldMap.cityPortalCoords === "object") delete p.worldMap.cityPortalCoords;
  if (typeof p.editMode !== "boolean") p.editMode = false;
  if (
    typeof window !== "undefined" &&
    window.GameStorage &&
    typeof window.GameStorage.isOnlineMode === "function" &&
    window.GameStorage.isOnlineMode()
  ) {
    p.editMode = false;
  }
  if (p.worldMap && p.worldMap.cells && typeof p.worldMap.cells === "object") {
    Object.keys(p.worldMap.cells).forEach((k) => {
      const c = p.worldMap.cells[k];
      if (!c || typeof c !== "object") return;
      if (!Array.isArray(c.defeated)) c.defeated = [];
      if (!Array.isArray(c.defeatedUnits)) c.defeatedUnits = [];
      if (!Array.isArray(c.mobPreviews)) c.mobPreviews = [];
    });
  }
  const mpv =
    GAME_CONFIG.worldMap && typeof GAME_CONFIG.worldMap.mobPreviewVersion === "number"
      ? GAME_CONFIG.worldMap.mobPreviewVersion
      : 0;
  if (p.worldMap && p.worldMap.cells && typeof p.worldMap.cells === "object" && mpv > 0) {
    const prevGen = p.worldMap.mobPreviewGeneration;
    if (prevGen !== mpv) {
      Object.keys(p.worldMap.cells).forEach((k) => {
        const c = p.worldMap.cells[k];
        if (c && typeof c === "object" && Array.isArray(c.mobPreviews)) c.mobPreviews = [];
      });
      p.worldMap.mobPreviewGeneration = mpv;
    }
  }
  ensurePlayerCompanions(p);
  ensureActorProfessionProgress(p);
  if (Array.isArray(p.companions)) {
    p.companions.forEach((c) => ensureActorProfessionProgress(c));
  }
}

let onlineSaveDebounceTimer = null;

function save(opts) {
  if (!inGameSession || activeCharacterSlotIndex == null || !player) return;
  ensureCharacterRoster();
  characterRoster.slots[activeCharacterSlotIndex] = player;
  const flush = !!(opts && opts.flush);
  if (
    !flush &&
    typeof window !== "undefined" &&
    window.GameStorage &&
    window.GameStorage.isOnlineMode()
  ) {
    if (onlineSaveDebounceTimer) clearTimeout(onlineSaveDebounceTimer);
    onlineSaveDebounceTimer = setTimeout(() => {
      onlineSaveDebounceTimer = null;
      void persistCharacterRoster();
    }, 500);
    return;
  }
  if (onlineSaveDebounceTimer) {
    clearTimeout(onlineSaveDebounceTimer);
    onlineSaveDebounceTimer = null;
  }
  void persistCharacterRoster();
}

function addEquipmentBonusStat(out, key, value) {
  const nk = normalizeEquipmentStatKey(key);
  if (!nk || typeof value !== "number" || !Number.isFinite(value)) return;
  const next = nk === "stamina" || nk === "hp" ? Math.floor(value) : value;
  out[nk] = (out[nk] || 0) + next;
}

function getEquipmentSetBonusStats(equipment) {
  const bonuses = GAME_CONFIG.mmoEquipmentSetBonuses;
  if (!bonuses || typeof bonuses !== "object") return {};
  const eq = equipment && typeof equipment === "object" ? equipment : emptyEquipment();
  const counts = {};
  EQUIP_SLOTS.forEach((s) => {
    const n = eq[s.id];
    if (!n) return;
    const def = getItemDef(n);
    const setName = def && typeof def.set === "string" ? def.set.trim() : "";
    if (!setName) return;
    counts[setName] = (counts[setName] || 0) + 1;
  });
  const out = {};
  Object.keys(counts).forEach((setName) => {
    const setCfg = bonuses[setName];
    if (!setCfg || typeof setCfg !== "object") return;
    const c = counts[setName];
    let best = 0;
    Object.keys(setCfg).forEach((thresholdRaw) => {
      const threshold = parseInt(thresholdRaw, 10);
      if (!Number.isFinite(threshold) || c < threshold) return;
      if (threshold > best) best = threshold;
    });
    if (best <= 0) return;
    const stats = setCfg[String(best)];
    if (!stats || typeof stats !== "object") return;
    Object.entries(stats).forEach(([k, v]) => {
      if (String(k).startsWith("_")) return;
      addEquipmentBonusStat(out, k, v);
    });
  });
  return out;
}

function countEquippedSetPieces(equipment, setName) {
  const want = typeof setName === "string" ? setName.trim() : "";
  if (!want) return 0;
  const eq = equipment && typeof equipment === "object" ? equipment : emptyEquipment();
  let count = 0;
  EQUIP_SLOTS.forEach((s) => {
    const n = eq[s.id];
    if (!n) return;
    const def = getItemDef(n);
    if (def && def.set === want) count += 1;
  });
  return count;
}

function tryProcThornbackGraveguardBleed(st, attackerFoe, receivedDamage) {
  if (!attackerFoe || attackerFoe.hp <= 0) return;
  if (typeof player === "undefined" || !player || !player.equipment) return;
  const pieces = countEquippedSetPieces(player.equipment, "Thornback Graveguard Set");
  if (pieces < 3) return;
  if (Math.random() >= 0.15) return;
  const base = Math.max(1, Math.floor(Number(receivedDamage) || 0));
  const dot = Math.max(1, Math.floor(base * 0.08));
  if (!attackerFoe.combat || typeof attackerFoe.combat !== "object") attackerFoe.combat = {};
  attackerFoe.combat.bleedTurns = Math.max(attackerFoe.combat.bleedTurns || 0, 2);
  attackerFoe.combat.bleedDamage = Math.max(attackerFoe.combat.bleedDamage || 0, dot);
  appendFightLog(`${attackerFoe.name} is bleeding from Thornback Graveguard spikes.`);
}

function getEquipmentForCombatMember(member, actor) {
  if (member?.kind === "hero" && typeof player !== "undefined" && player?.equipment) return player.equipment;
  if (actor?.equipment && typeof actor.equipment === "object") return actor.equipment;
  if (member?.kind === "companion" && typeof member.companionSlotIndex === "number") {
    const comp = player?.companions?.[member.companionSlotIndex];
    if (comp?.equipment) return comp.equipment;
  }
  return null;
}

function applyFoePhysResDown(foe, pct, turns) {
  if (!foe) return;
  if (!foe.combat) initFoeCombatRuntime(foe);
  const t = Math.max(1, Math.floor(turns));
  foe.combat.physResDownPct = Math.max(foe.combat.physResDownPct || 0, Math.max(0, pct));
  foe.combat.physResDownTurns = Math.max(foe.combat.physResDownTurns || 0, t);
}

function applyFoeCrippleFromSet(foe, turns) {
  if (!foe) return;
  if (!foe.combat) initFoeCombatRuntime(foe);
  const t = Math.max(1, Math.floor(turns));
  foe.combat.staggerSkillTaxTurns = Math.max(foe.combat.staggerSkillTaxTurns || 0, t);
}

function applyFoeAccuracyDown(foe, pct, turns, equipment) {
  if (!foe) return;
  if (!foe.combat) initFoeCombatRuntime(foe);
  const t = Math.max(1, Math.floor(turns));
  foe.combat.accDownPct = Math.max(foe.combat.accDownPct || 0, Math.max(0, pct));
  foe.combat.accDownTurns = Math.max(foe.combat.accDownTurns || 0, t);
  const eq = equipment || (typeof player !== "undefined" ? player.equipment : null);
  if (combatState) tryProcBannerlessMagResOnAccuracyDebuff(combatState, eq, foe);
  if (combatState) tryProcStillnessMagDmgOnAccuracyDebuff(combatState, eq, foe);
}

function applyFoeMagDmgDown(foe, pct, turns) {
  if (!foe) return;
  if (!foe.combat) initFoeCombatRuntime(foe);
  const t = Math.max(1, Math.floor(turns));
  foe.combat.magDmgDownPct = Math.max(foe.combat.magDmgDownPct || 0, Math.max(0, pct));
  foe.combat.magDmgDownTurns = Math.max(foe.combat.magDmgDownTurns || 0, t);
}

