function sumEquippedBonusStatsFromEquipment(equipment) {
  const out = {
    str: 0,
    dex: 0,
    vit: 0,
    int: 0,
    stamina: 0,
    hp: 0,
    physDamage: 0,
    physicalResist: 0,
    magicResist: 0,
    skillPower: 0,
    crit: 0,
    critDamage: 0,
    accuracy: 0,
    evasion: 0,
    healingReceived: 0,
    statusResist: 0,
    maxHpPct: 0
  };
  const eq = equipment && typeof equipment === "object" ? equipment : emptyEquipment();
  const progressOwner = arguments.length >= 2 ? arguments[1] : player;
  EQUIP_SLOTS.forEach((s) => {
    const n = eq[s.id];
    if (!n) return;
    if (s.id === "pet") {
      const petStats = getEquippedPetBonusStats(eq, progressOwner);
      Object.entries(petStats).forEach(([k, v]) => {
        if (typeof v === "number" && Number.isFinite(v)) addEquipmentBonusStat(out, k, v);
      });
      return;
    }
    const def = getItemDef(n);
    if (!def) return;
    const scaledBonusStats = getScaledItemBonusStats(def, n);
    for (const [k, v] of Object.entries(scaledBonusStats)) {
      addEquipmentBonusStat(out, k, v);
    }
  });
  const setBonusStats = getEquipmentSetBonusStats(eq);
  Object.entries(setBonusStats).forEach(([k, v]) => {
    if (typeof v === "number" && Number.isFinite(v)) out[k] = (out[k] || 0) + v;
  });
  out.stamina = Math.max(0, Math.min(MAX_STAMINA_FROM_GEAR, Math.floor(out.stamina)));
  out.hp = Math.max(0, Math.floor(out.hp));
  return out;
}

function totalVitFromPlayerRecord(p) {
  if (!p) return 0;
  const base = typeof p.vit === "number" && Number.isFinite(p.vit) ? p.vit : 10;
  const gearVit = sumEquippedBonusStatsFromEquipment(p.equipment, p).vit;
  return base + gearVit;
}

function computeMaxHp(p) {
  const sys = getStatSystem();
  const lv = typeof p.level === "number" && p.level >= 1 ? p.level : 1;
  const baseHp = getBaseHpFromLevel(lv);
  const vitPer = typeof sys.vitHpPerPoint === "number" ? sys.vitHpPerPoint : 5;
  const gear = sumEquippedBonusStatsFromEquipment(p.equipment || emptyEquipment(), p);
  const gearHp = gear.hp || 0;
  const hpPct = Math.max(0, Number(gear.maxHpPct) || 0);
  const flat = baseHp + vitPer * totalVitFromPlayerRecord(p) + gearHp;
  return Math.max(1, Math.floor(flat * (1 + hpPct / 100)));
}

function splitItemInstanceName(name) {
  const raw = typeof name === "string" ? name : "";
  if (!raw) return { baseName: "", rarityId: "" };
  const sep = raw.lastIndexOf("@@");
  if (sep <= 0) return { baseName: raw, rarityId: "" };
  return {
    baseName: raw.slice(0, sep),
    rarityId: normalizeItemRarityId(raw.slice(sep + 2))
  };
}

function getItemBaseName(name) {
  return splitItemInstanceName(name).baseName;
}

function getItemInstanceRarityId(name) {
  return splitItemInstanceName(name).rarityId;
}

function makeRarityItemInstanceName(baseName, rarityId) {
  const base = String(baseName || "").trim();
  if (!base) return "";
  const rarity = normalizeItemRarityId(rarityId);
  return `${base}@@${rarity}`;
}

