const PROFESSION_GATHERING_TABLES =
  typeof GatheringTables !== "undefined" && GatheringTables.PROFESSION_GATHERING_TABLES
    ? GatheringTables.PROFESSION_GATHERING_TABLES
    : Object.freeze({});

function isConfiguredMonsterMaterialName(name) {
  const n = String(name || "").trim();
  if (!n) return false;
  if (!knownMonsterMaterialNamesCache.built) {
    knownMonsterMaterialNamesCache.built = true;
    const tables = GAME_CONFIG && GAME_CONFIG.monsterDropTables;
    if (tables && typeof tables === "object") {
      Object.values(tables).forEach((tbl) => {
        const mats = tbl && Array.isArray(tbl.materials) ? tbl.materials : [];
        mats.forEach((m) => {
          if (m && typeof m.name === "string" && m.name.trim()) {
            knownMonsterMaterialNamesCache.names.add(m.name.trim());
          }
        });
      });
    }
  }
  return knownMonsterMaterialNamesCache.names.has(n);
}

/** Renamed items: old base names in saves / exports still resolve to the new definition. */
const ITEM_DEF_LEGACY_BASE_NAMES = Object.freeze({
  "Mirage Hood": "Mirage Helm",
  "Thick Scale": "Stone Scale",
  "Spirit Bark": "Bark Fragment",
  "Antler Fragment": "Antler Piece",
  "Toxic Extract": "Toxic Essence",
  "Illusion Fragment": "Illusion Essence",
  "Claw Gloves": "Claw Ring",
  "Rockstep Boots": "Rock Serpent Boots",
  "Earth Loop": "Serpent Grip",
  "Stone Helm": "Stone Lizzard Helmet",
  "Stonehide Armor": "Stonescale Armor",
  "Core Leggings": "Stonescale Leggings",
  "Earthpulse Amulet": "Stonepulse Amulet",
  "Earthcaller Staff": "Stonecaller",
  "Crystal Band": "Stonekind Band"
});

function getItemDef(name) {
  const baseName = getItemBaseName(name);
  const lookupName = ITEM_DEF_LEGACY_BASE_NAMES[baseName] || baseName;
  const direct = GAME_CONFIG.items[lookupName];
  if (direct) return direct;
  if (isConfiguredMonsterMaterialName(baseName) || PROFESSION_GATHERING_MATERIALS.has(baseName)) {
    return {
      type: "resource",
      image: "Assets/Resources/energy-cell.svg",
      description: "Crafting material dropped by monsters.",
      bonusSkills: [],
      bonusStats: {}
    };
  }
  return null;
}

